We will use the fact that the $\sigma$-algebra generated by  a set of scalar-valued functions $\mathcal{F}$ on a common domain coincides with the collection
\begin{equation}
\label{distroembedding extension eq}
\Big\{\big[(f_n)_{n=1}^\infty\in A\big]:(f_n)_{n=1}^\infty\in\mathcal{F}^\mathbb{N}\text{ and }A\in\mathcal{B}(\mathbb{R}^\mathbb{N})\Big\}.
\end{equation}
In our case, $\mathcal{F}$ is the collection of all representatives from members of $W$. For any $(f_n)_{n=1}^\infty$, $(g_n)_{n=1}^\infty$ in $W$ and $A, B\in\mathcal{B}(\mathbb{R}^\mathbb{N})$, because $T$ preserves joint distributions,
\begin{align*}
\big|[(f_n)_{n=1}^\infty\in A]\setminus [(g_n)_{n=1}^\infty\in B]\big| &= \big|[(f_n)_{n=1}^\infty\times (g_n)_{n=1}^\infty \in A\times B^c]\big|\\
&= \big|[(Tf_n)_{n=1}^\infty\times (Tg_n)_{n=1}^\infty \in A\times B^c]\big|\\
&= \big|[(Tf_n)_{n=1}^\infty\in A]\setminus [(Tg_n)_{n=1}^\infty\in B]\big|.
\end{align*}
This implies that the map $\sigma(W)\ni \big[(f_n)_{n=1}^\infty\in A\big] = C\mapsto \varphi(C) = \big[(Tf_n)_{n=1}^\infty\in A\big]\in\sigma(T[W])$ is a well-defined measure algebra isomorphism, and it thus induces an onto distributional embedding $T:L_0(\sigma(W))\to L_0(\sigma(T[W]))$, via $\tilde T\chi_{C} = \chi_{\varphi(C)}$ ($\tilde T$ is first defined on simple functions, where it is an isometry with respect to the standard Polish metric of $L_0$ mentioned in \Cref{measure theory notation}, and then extended to $L_0(\sigma(W))$). It is easy to see that such a $\tilde T$ is a homomorphism. Uniqueness is verified as follows: if $S =L_0(\sigma(W))\to L_0$ is a distributional embedding extending $T$ and $[(f_n)_{n=1}^\infty\in A\big]$ is as in \eqref{distroembedding extension eq}, then, because $S$ preserves joint distributions,
\begin{align*}
\big|\big[S\chi_{[(f_n)_{n=1}^\infty\in A]} \neq \tilde T\chi_{[(f_n)_{n=1}^\infty\in A]}\big]\big| &= \big|\big[S\chi_{[(f_n)_{n=1}^\infty\in A]}\in\{1\}\big]\triangle\big[(Tf_n)_{n=1}^\infty\in A\big]\big|\\
&= \big|\big[S\chi_{[(f_n)_{n=1}^\infty\in A]}\in\{1\}\big]\triangle\big[(Sf_n)_{n=1}^\infty\in A\big]\big|\\
& = \big|\big[\chi_{[(f_n)_{n=1}^\infty\in A]}\in\{1\}\big]\triangle\big[(f_n)_{n=1}^\infty\in A\big]\big| = 0.\qedhere
\end{align*}

\label{constructing associated haar system in the more familiar way}
Let $F = \{k_0<\cdots<k_n\}$ be a finite subset of $\mathbb{N}_0$. Define $\mathcal{B}^F_{[0,1)} = \mathcal{D}^{k_0}$ and, for $1\leq i\leq n$ and $I\in\mathcal{D}^i$, let $\mathcal{B}^F_I = \{L\in\mathcal{D}^{k_i}: L\subset [b^F_{\pi(I)} = \varepsilon(I)]\}.$ Then, for $0\leq i\leq n$ and $I\in\mathcal{D}^i$,
\begin{equation*}
b^F_I = \sum_{L\in \mathcal{B}^F_I}h_L,
\end{equation*}
and, in particular, $b_I^F$ is a linear combination of $(h_L)_{L\in\mathcal{D}^{k_i}}$.

For $1\leq i\leq n$ and $I\in\mathcal{D}^i$, $h_I = r_i\chi_{[h_{\pi(I)}=\varepsilon(I)]}$. Using that $J_F$ is a homomorphism,
  \begin{equation}\label{eq:22}
    b_I^F = J_Fh_I =  r_{k_i}\chi_{[b^F_{\pi(I)}=\varepsilon(I)]} =\Big(\sum_{L\in\mathcal{D}^{k_i}}h_L\Big) \chi_{[b^F_{\pi(I)}=\varepsilon(I)]} = \sum_{L\in\mathcal{B}^F_I}h_L,
  \end{equation}
where the last equality follows from $b_{\pi(I)}^F$ being $\sigma(\mathcal{D}^{k_i})$-measurable.

\label{haar system space}
A Haar system space is the completion $X$ of the vector space $\langle\{ \chi_I:I\in\mathcal{D}\}\rangle = \langle\{\chi_{[0,1)}\}\cup\{h_I:I\in\mathcal{D}\}\rangle$ under a norm $\|\cdot\|_X$ satisfying:
\begin{enumerate}[label=(\alph*)]

\item $\|\chi_{[0,1)}\|_X = 1$ and

\item for $f,g\in \langle\{ \chi_I:I\in\mathcal{D}\}\rangle$ such that $\mathrm{dist}(|f|) = \mathrm{dist}(|g|)$, $\|f\|_X = \|g\|_X$.

\end{enumerate}

\label{square function continuity}
The square function satisfies the so-called weak type $(1,1)$ estimate
\begin{equation}
\label{weak type (1,1)}
\lambda\big|[S(f)\geq \lambda]\big| \leq \sqrt{e}\|f\|_1,
\end{equation}
where $f\in L_1^0$ and $\lambda >0$ (see, e.g., \cite[Theorem 8.2]{AdamOse:2012}). This suggests that $S:L_1^0\to L_0$ is well-defined and continuous, with the target space equipped with the topology of convergence in measure, because, for $f,g\in L_1^0$, $|S(f) - S(g)|\leq |S(f-g)|$ pointwise.

\label{haar system unconditional in hardy}
Let $X$ be a Haar system space.
\begin{enumerate}[label=(\alph*)]

\item\label{haar system unconditional in hardy a} The Haar system $(h_I)_{I\in\mathcal{D}}$ is, by definition, a 1-unconditional basis for $H_X$.

\item\label{haar system unconditional in hardy b} By \cite[Theorem 1.d.6 (ii)]{lindenstrauss:tzafriri:1979:partII}, $(h_I)_{I\in\mathcal{D}}$ is an unconditional basis for $X$ if and only the norms $\|\cdot\|_X$ and $\|\cdot\|_{H_X}$ are equivalent.

\end{enumerate}

\label{hardy spaces without c_0}
For a Haar system space $X$, the identity map
\[id:\big(\langle\{h_I:I\in\mathcal{D}\}\rangle,\|\cdot\|_{H_X}\big)\to L_1^0\]
extends to a bounded linear injection on $H_X$. We may thus naturally identify $H_X$ with a subspace of $L_1^0$, and more precisely, we have
\begin{equation}
\label{Hardy space included}
H_X \subset \{f\in L_1^0: S(f) \in X\}.
\end{equation}
In particular, the defining formula for $\|\cdot\|_{H_X}$ extends to the completion of $\langle\{h_I:I\in\mathcal{D}\}\rangle$. That is for every $f\in H_X$,
\begin{equation}
\label{square function well-defined in completion}
\|f\|_{H_X} = \|S(f)\|_X.
\end{equation}
If, furthermore, $\|\cdot\|_X\not\asymp\|\cdot\|_\infty$, then
\[H_X = \{f\in L_1^0: S(f) \in X\}.\]

\phantom{a}\label{rem:hardy}
\begin{enumerate}[label=(\alph*)]

\item\label{rem:hardy:a} Square function-distributional embeddings differ from distributional embeddings. Two simple examples illustrate the gap. Let $(\mathcal{B}_I)_{I\in\mathcal{D}}$ be pairwise disjoint subsets of $\mathcal{D}$ such that, for each $I\in\mathcal{D}$, $\bigcup \mathcal{B}_I = I$. Then the map $h_I \mapsto \sum_{J\in \mathcal{B}_I} h_J$ defines a square function distributional embedding, but, unless $\mathcal{B}_I = \{I\}$ for all $I\in\mathcal{D}$, it is not a distributional embedding. Conversely, if $i\mapsto k_i$ is a not increasing injection on $\mathbb{N}_0$, then the extension $\tilde J$, in the sense of \Cref{distroembedding extension}, of the distributional embedding $r_i\stackrel{J}{\mapsto} r_{k_i}$ is not a square function-distributional embedding.

\item\label{rem:hardy:b} To our knowledge, there is no meaningful analogue of \Cref{distroembedding extension} for square function-distributional embeddings. Specifically, if $J:Z\to L_1^0$ is a square function-distributional embedding, one cannot in general expect the existence of a square function-distributional embedding $\tilde J:L_1^0(\sigma(Z))\to L_1^0$ extending $J$. This leads to the following phenomenon in a Haar system space $X$. If $Z$ is a complemented subspace of $X^0$, then any distributional copy of $Z$ in $X^0$ is also complemented (see \Cref{lem:distributional-copy-complemented}). However, there are situations, for instance when $X=L_1$, in which a subspace $Z\subset H_X$ is complemented, yet admits square function-distributional copies that are not complemented (see \Cref{thm:tree-spaces-uncomplemented}).

\end{enumerate}

\label{standard half compressions remark}
Let $f\in L_0$. Then, $T_{[0,1/2)}f$ and $T_{[1/2,1)}f$ are disjointly supported and
\[\mathrm{dist}(T_{[0,1/2)}f+T_{[1/2,1)}f) = \mathrm{dist}(f).\]
If $f\in L_1^0$, then, for $T = T_{[0,1/2)}$ or $T_{[1/2,1)}$, letting $S$ denote the square function operator,
\begin{equation}
\label{standard half compressions play nice with square function}
TS(f) = S(Tf).
\end{equation}
In particular, if $X$ is a Haar system space and $Y = X^0$ or $H_X$, then, for all $f\in Y$, $Tf\in Y$ and
\begin{equation}
\label{standard half compressions are 2-embeddings}
(1/2)\|f\|_Y\leq \|Tf\|_Y \leq \|f\|_Y.
\end{equation}

\label{disjoint sum is really a sum}
Let $X$ be a Haar system space, $Y = X^0$ or $H_X$, and $Z$, $W$ be subspaces of $Y$. \Cref{standard half compressions remark} yields
\[(Z\oplus W)^+_{\mathrm{disj}}\simeq \mathbb R\oplus Z\oplus W.\]

\label{def independent sum}
Let $X$ be a Haar system space and let $Y=X^0$ or $H_X$. Let $(Z_n)_{n=1}^\infty$ be a sequence of subspaces of $Y$. Let $J_n:Z_n\to Y$, $n\in\mathbb{N}$, be embeddings such that:
\begin{enumerate}[label=(\alph*)]
\item if $Y=X^0$, the operators $J_n$ are distributional embeddings with independent ranges;
\item if $Y=H_X$, the operators $J_n$ are square function-distributional embeddings with square function-independent ranges.
\end{enumerate}
The independent sum of $(Z_n)_{n=1}^\infty$ is
\[\big(\oplus_{n=1}^\infty Z_n\big)_{Y,\mathrm{ind}} = \big[\big(J_n(Z_n)\big)_{n=1}^\infty\big].\]

\label{rem:nth-successor-BRS-space}
  Note that if $\gamma$ is a countable ordinal, then, for every $n\in \mathbb{N}$,
  \begin{equation*}
    R_{\gamma + n}^{Y} = \langle \{ h_I : I\in \mathcal{D}_{n-1} \} \rangle + \sum_{I\in \mathcal{D}^n} T_I(R_\gamma^{Y}),
  \end{equation*}
  where $T_I$ is as in \Cref{def  compression}. The Bourgain-Rosenthal-Schechtman spaces $R_\alpha^Y$ for $\omega\le \alpha\le \omega\cdot 2$ are illustrated in \Cref{fig:BRS-infinite}.

Let $Z = (\oplus_{n=0}^{\infty} R_{\gamma + n}^{Y})_{Y,\mathrm{ind}}$.
  We can write
  \begin{equation*}
     Z = \bigl[\bigl(J_{F_n}(R_{\gamma + n}^{Y})\bigr)_{n=0}^{\infty}\bigr],
  \end{equation*}
  where $(F_n)_{n=0}^{\infty}$ is a sequence of pairwise disjoint infinite subsets of $\mathbb{N}_0$ and the embeddings $J_{F_n}$ are as in \Cref{notation of subsequences of the levels}~\ref{notation of subsequences of the levels b}. Now we define four projections on $\langle \{ b^{F_n}_I : I\in \mathcal{D}, n\in \mathbb{N}_0 \}  \rangle$ by putting, for $f = \sum_{n=0}^N \sum_{I\in \mathcal{D}} a_I^nb_I^{F_n}$,
  \begin{align*}
    P_0 f &= \sum_{I\in \mathcal{D}} a_I^0 b_I^{F_0},
    & P_1 f &= \sum_{n=1}^N a_{[0,1)}^n b_{[0,1)}^{F_n}, \\
    P_2 f &= \sum_{n=0}^N \sum_{\substack{I\in \mathcal{D}\\ I\subset [0,\frac{1}{2})}} a_I^n b_I^{F_n},
    & P_3 f &= \sum_{n=0}^N \sum_{\substack{I\in \mathcal{D}\\ I\subset [\frac{1}{2},1)}} a_I^n b_I^{F_n}.
  \end{align*}
  We will show that the projections $P_0$, $P_1$, $P_2$, and $P_3$ are bounded. If $Y = H_X$, this follows from the $1$-unconditionality of the Haar system. If $Y = X^0$, then it follows by repeatedly applying the following basic observation: If $n\in \mathbb{N}$ and $I\in \mathcal{D}$ are such that $a_J^n = 0$ for all $J \subset I$, then $f + a_I^n b_I^{F_n}$ and $f - a_I^nb_I^{F_n}$ have the same distribution, so
  \begin{equation}\label{eq:5}
    \|f\|_X \le \frac{1}{2}\bigl( \|f + a_I^nb_I^{F_n}\|_X + \|f - a_I^n b_I^{F_n}\|_X \bigr) = \|f + a_I^n b_I^{F_n}\|_X.
  \end{equation}
  Thus, $P_1$, $P_2$, $P_3$, and $P_4$ extend to bounded linear projections on $[(J_{F_n}(Y))_{n=0}^{\infty}]$ that map $Z$ into itself (this follows from \Cref{rem:nth-successor-BRS-space}).
  Put $Z_0 = P_0(Z)$, $U = P_1(Z)$, $V = P_2(Z)$, and $W = P_3(Z)$.
  Then $Z\simeq Z_0 \oplus U \oplus V \oplus W$, where $Z_0$ is isometric to~$R_\gamma^{Y}$.

  We will now show that $U\simeq U \oplus U$, and $V\simeq W\simeq Z$.
  The first statement holds because $U = [r_{\min(F_n)} : n\in \mathbb{N}]$. In particular, we have $U \simeq U \oplus \mathbb{R}$, and hence, $Z\simeq Z \oplus \mathbb{R}$. To prove that $V\simeq W\simeq Z$, we define, for $I = [0,\frac{1}{2})$ or $[\frac{1}{2},1)$, the operator $\widetilde{T}_I$ on $\langle \{ b_I^{F_n} : I\in \mathcal{D}, n\in \mathbb{N}_0 \} \rangle$ by
  \begin{equation*}
    \widetilde{T}_I\Bigl( \sum_{n=0}^N J_{F_n}f_n \Bigr) = \sum_{n=0}^N J_{F_n}\bigl( T_I f_n\bigr)
  \end{equation*}
  for $f_0,\dots,f_N\in \langle \{ h_I : I\in \mathcal{D} \} \rangle$. Let $f = \sum_{n=1}^N J_{F_n} f_n$, and observe that $\widetilde{T}_{[0,\frac{1}{2})}f$ and $\widetilde{T}_{[\frac{1}{2},1)}f$ have the same distribution. The same is true for their square functions $S(\widetilde{T}_{[0,\frac{1}{2})}f)$ and $S(\widetilde{T}_{[\frac{1}{2},1)}f)$ (see \Cref{standard square function distributional isomorphism}). Thus,
  \begin{equation*}
    \|\widetilde{T}_{[0,\frac{1}{2})}f\|_Y
    = \frac{1}{2} \bigl( \|\widetilde{T}_{[0,\frac{1}{2})}f\|_Y + \|\widetilde{T}_{[\frac{1}{2},1)}f\|_Y \bigr)
    \ge \frac{1}{2} \|\widetilde{T}_{[0,\frac{1}{2})}f + \widetilde{T}_{[\frac{1}{2},1)}f\|_Y.
  \end{equation*}
  On the other hand, \eqref{eq:5} implies that
  \begin{equation*}
    \|\widetilde{T}_{[0,\frac{1}{2})}f\|_Y \le \|\widetilde{T}_{[0,\frac{1}{2})}f + \widetilde{T}_{[\frac{1}{2},1)}f\|_Y.
  \end{equation*}
  Note that $\widetilde{T}_{[0,\frac{1}{2})}f + \widetilde{T}_{[\frac{1}{2},1)}f$ has the same distribution as $f$, and the same is true for their square functions. Hence,
  \begin{equation*}
    \|f\|_Y = \|\widetilde{T}_{[0,\frac{1}{2})}f + \widetilde{T}_{[\frac{1}{2},1)}f\|_Y \asymp \|\widetilde{T}_{[0,\frac{1}{2})}f\|_Y,
  \end{equation*}
  and so, $\widetilde{T}_{[0,\frac{1}{2})}$ extends to an embedding of $[(J_{F_n}(Y))_{n=0}^{\infty}]$ into itself. The same is true for $\widetilde{T}_{[\frac{1}{2},1)}$.
  Now observe that $\widetilde{T}_{[0,\frac{1}{2})}(Z)$ isometric to~$V$ (via the shift $b_I^n\mapsto b_I^{n+1}$), and $\widetilde{T}_{[\frac{1}{2},1)}(Z)$ isometric to~$W$.

  Finally, since $Z_0$ and $U$ are complemented in $Z$ and isomorphic to their squares, we conclude that $Z \simeq Z \oplus U$ and $Z \simeq Z \oplus Z_0$. Hence,
  \begin{equation*}
    Z \simeq Z_0 \oplus U \oplus V \oplus W \simeq Z_0 \oplus U\oplus Z \oplus Z \simeq Z \oplus Z.\qedhere
  \end{equation*}

\label{prop:R-alpha-Y-0-isomorphic-to-its-square}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$.
  Then, for every countable ordinal $\omega\le \alpha < \omega_1$ the space $R_\alpha^{Y}$ is isomorphic to its square and to its hyperplanes.

It can be easily shown by transfinite induction that for every $\omega \le  \alpha < \omega_1$, $R_\alpha^{Y}$ contains a complemented subspace isomorphic to $R_\omega^{Y}$. By \Cref{lem:R-omega-Y-0-isomorphic-to-its-square}, $R_\omega^{Y}\simeq R_\omega^{Y}\oplus \mathbb{R}$, hence, $R_\alpha^{Y}$ is isomorphic to its hyperplanes as well.

  Now we use transfinite induction to show that $R_\alpha^{Y}$ is isomorphic to its square for all $\omega \le \alpha < \omega_1$. For $\alpha = \omega$, this is proved in \Cref{lem:R-omega-Y-0-isomorphic-to-its-square}, so we assume that $\alpha > \omega$ and that the statement holds for all infinite countable ordinals $\beta < \alpha$.
  In the following, replace ``$\equiv^\mathrm {dist}$'' with ``$\equiv^{S\text{-dist}}$'' if $Y=H_X$.

  \noindent \textbf{Case 1.} $\alpha = \gamma + \omega$ for some limit ordinal $\gamma < \omega_1$.
  Using \Cref{canonical properties of independent sums}~\ref{canonical properties of independent sums d}, we can write
  \begin{align*}
    R_\alpha^{Y} &= \bigl(\oplus_{\beta < \alpha} R_\beta^{Y}\bigr)_{Y,\mathrm{ind}}\\
    &\equiv^\mathrm{dist} \Bigl( \bigl(\oplus_{\beta < \gamma} R_\beta^{Y}\bigr)_{Y,\mathrm{ind}} \oplus \bigl(\oplus_{n=0}^{\infty} R_{\gamma + n}^{Y} \bigr)_{Y,\mathrm{ind}} \Bigr)_{Y,\mathrm{ind}}\\
    &\simeq  \bigl(\oplus_{\beta < \gamma} R_\beta^{Y}\bigr)_{Y,\mathrm{ind}} \oplus \bigl(\oplus_{n=0}^{\infty} R_{\gamma + n}^{Y} \bigr)_{Y,\mathrm{ind}} \\
    &\simeq R_\gamma^{Y} \oplus \bigl(\oplus_{n=0}^{\infty} R_{\gamma + n}^{Y} \bigr)_{Y,\mathrm{ind}}.
  \end{align*}
  By the induction hypothesis, the space $R_\gamma^{Y}$ is isomorphic to its square, and by \Cref{lem:R-omega-Y-0-isomorphic-to-its-square}, the same is true for $\bigl(\oplus_{n=0}^{\infty} R_{\gamma + n}^{Y} \bigr)_{Y,\mathrm{ind}}$. Thus, $ R_\alpha^{Y} \simeq  R_\alpha^{Y} \oplus R_\alpha^{Y} $.

  \noindent \textbf{Case 2.} $\alpha = \sup\{ \beta < \alpha : \beta \text{ is a limit ordinal} \}$. Then we can pick a strictly increasing sequence $(\alpha_n)_{n=1}^{\infty}$ of countable limit ordinals with supremum $\alpha$. Let $B = \{ \beta < \alpha : \beta\ne \alpha_n \text{ for all }n\in \mathbb{N} \}$. Using \Cref{canonical properties of independent sums}~\ref{canonical properties of independent sums d} and~\ref{canonical properties of independent sums b}, we obtain
  \begin{align*}
    R_\alpha^{Y} = \bigl(\oplus_{\beta < \alpha} R_\beta^{Y}\bigr)_{Y,\mathrm{ind}}
    &\equiv^\mathrm{dist} \Bigl( \bigl(\oplus_{n=1}^{\infty} R_{\alpha_n}^{Y} \bigr)_{Y,\mathrm{ind}} \oplus \bigl(\oplus_{\beta\in B} R_{\beta}^{Y} \bigr)_{Y,\mathrm{ind}} \Bigr)_{Y,\mathrm{ind}}\\
    &\equiv^\mathrm{dist} \Bigl( \bigl(\oplus_{n=1,\beta < \alpha_n}^{\infty} R_\beta^{Y}\bigr)_{Y,\mathrm{ind}} \oplus \bigl(\oplus_{\beta\in B} R_{\beta}^{Y} \bigr)_{Y,\mathrm{ind}} \Bigr)_{Y,\mathrm{ind}}.
  \end{align*}
  In the first independent sum, each space $R_\beta^{Y}$, $\beta < \alpha$, appears infinitely many times. Thus, by \Cref{canonical properties of independent sums}~\ref{canonical properties of independent sums d} and~\ref{canonical properties of independent sums c}, we have
  \begin{equation}\label{eq:6}
    R_\alpha^{Y} \equiv^\mathrm{dist} \bigl(\oplus_{n=1,\beta < \alpha}^{\infty} R_\beta^{Y}\bigr)_{Y,\mathrm{ind}}.
  \end{equation}
  This implies that $R_\alpha^{Y} \equiv^\mathrm{dist} \bigl(R_\alpha^{Y} \oplus R_\alpha^{Y} \bigr)_{Y,\mathrm{ind}}$, so $R_\alpha^{Y}$ is isomorphic to its square.

  \noindent \textbf{Case 3.} $\alpha = \beta + 1$ is a successor ordinal. Then, by \Cref{disjoint sum is really a sum} and the induction hypothesis,
  \begin{align*}
    R^{Y}_\alpha = \big(R^{Y}_\beta\oplus R^{Y}_\beta\big)^+_{\mathrm{disj}}
    &\simeq \mathbb{R} \oplus R^{Y}_\beta\oplus R^{Y}_\beta\\
    &\simeq \mathbb{R} \oplus (R^{Y}_\beta\oplus R^{Y}_\beta)\oplus (\mathbb{R} \oplus  R^{Y}_\beta\oplus R^{Y}_\beta).\\
    &\simeq R^{Y}_\alpha \oplus R^{Y}_\alpha.\qedhere
  \end{align*}

\label{definition disjointly branching}
A non-empty subcollection $\mathcal{T}$ of $[\mathbb{N}_0]^{<\infty}$ is called a disjointly branching tree if it satisfies the following:
\begin{enumerate}[label=(\alph*),]

\item\label{definition disjointly branching a} For every $A\in\mathcal{T}$ and $B\sqsubseteq A$, $B$ is in $\mathcal{T}$, i.e., $\mathcal{T}$ is downward closed.

\item\label{definition disjointly branching b}  For every $A,B\in\mathcal{T}$, $A\cap B\sqsubseteq A$.

\end{enumerate}

\phantom{a}
\label{remark on disjoint union}
\begin{enumerate}[label=(\alph*)]

\item\label{remark on disjoint union a} The construction in \Cref{disjointly branching tree operations} \ref{disjointly branching tree operations b} is always possible. Fix a pairwise disjoint family $(M_s)_{s\in S}$ of subsets of $\mathbb{N}_0$ such that $\# M_s = \#\cup \mathcal{T}_s$ for all $s\in S$. Let $\phi_s:\cup \mathcal{T}_s\to M_s$ denote the order preserving bijection and define $\mathcal{T}_s'=\{\phi_s(F):F\in\mathcal{T}_s\}$.

\item\label{remark on disjoint union b} The construction of $\sqcup_{s\in S}\mathcal{T}_s$ does not depend on the specific choice of copies $(\mathcal{T}'_s)_{s\in S}$ in the following sense: choosing different copies $(\mathcal{T}''_s)_{s\in S}$ produces a disjoint union which is as a partially ordered set isomorphic to the original one, as follows easily, e.g., from \Cref{what tree isomorphisms look like}.

\end{enumerate}

\label{exa:ordinal-trees}
\[\mathcal{T}_0 = \{\emptyset\},\;\mathcal{T}_1 = \{\emptyset,\{0\}\},\text{ and }\mathcal{T}_n = \{\emptyset,\{0\},\{0,1\},\ldots,\{0,1,\ldots,n-1\}\},\;n\in\mathbb{N}.\]
The tree $\mathcal{T}_\omega$ depends on the choice of copies $(\mathcal{T}'_n)_{n\in\mathbb{N}_0}$. If we let $M_0 = \emptyset$, $M_1 = \{0\}$, $M_2 = \{1,2\}$, $M_3 = \{3,4,5\}$, $M_4 = \{6,7,8,9\}$\ldots, and follow \Cref{remark on disjoint union} \ref{remark on disjoint union a} then
\begin{align*}
\mathcal{T}_\omega = &\{\emptyset\}\cup\big\{\{0\}\big\}\cup\big\{\{1\},\{1,2\}\big\}\cup\big\{\{3\},\{3,4\},\{3,4,5\}\big\}\cup\cdots,\\
\mathcal{T}_{\omega+1} = &\{\emptyset\}\cup\big\{\{0\}\big\}\cup\big\{\{0,1\}\big\}\cup\big\{\{0,2\},\{0,2,3\}\big\}\cup\big\{\{0,4\},\{0,4,5\},\{0,4,5,6\}\big\}\cup\cdots,\text{ and}\\
\mathcal{T}_{\omega+2} =& \{\emptyset\}\cup\big\{\{0\}\big\}\cup\big\{\{0,1\}\big\}\cup\big\{\{0,1,2\}\big\}\cup\big\{\{0,1,3\},\{0,1,3,4\}\big\}\cup\\
&\big\{\{0,1,5\},\{0,1,5,6\},\{0,1,5,6,7\}\big\}\cup\cdots.
\end{align*}
This is illustrated in \Cref{fig:trees-T-alpha}.
