\label{pushing up}
For every $0\leq\alpha<\omega_1$ and $n\in\mathbb{N}$,
\[\mathcal{T}_{\alpha+n} = \mathcal{T}_n\cup\Big\{\{0,\ldots,n-1\}\cup\{k+n:k\in F\}:F\in\mathcal{T}_\alpha\Big\}.\]

\label{BRS definition trees}
Let $X$ be a Haar system space and $Y = X^0$ or $H_X$. For every disjointly branching tree $\mathcal{T}$, we define the subspace of $Y$
\[R^{Y}_\mathcal{T} = \big[(Y_F)_{F\in\mathcal{T}}\big].\]

\label{showing these are really BRS spaces}
Let $X$ be a Haar system space. Then, for every $0\leq \alpha<\omega_1$,
\begin{equation*}
R_{\alpha}^{X^0} \equiv^\mathrm{dist} R_{\mathcal{T}_\alpha}^{X^0}\text{ and }R_{\alpha}^{H_X} \equiv^{S\text{-}\mathrm{dist}} R_{\mathcal{T}_\alpha}^{H_X}.
\end{equation*}

We focus on the case $Y = H_X$, as the other case is proved identically by modifying the notation. Because $\mathcal{T}_0 = \{\emptyset\}$, we clearly have $R_{\mathcal{T}_0}^{Y} = R^{Y}_0$. We will show the following, which yields the desired conclusion from \Cref{BRS definition sums}:
\begin{enumerate}[label=(\alph*)]

\item\label{showing these are really BRS spaces proof a} For every $\alpha<\omega_1$,
\[R_{\mathcal{T}_{\alpha+1}}^{Y} = \big(R^{Y}_{\mathcal{T}_{\alpha}}\oplus R^{Y}_{\mathcal{T}_{\alpha}}\big)^+_{\mathrm{disj}}.\]

\item\label{showing these are really BRS spaces proof b} For every limit ordinal $\alpha<\omega_1$,
\[R^Y_{\mathcal{T}_{\alpha}}\equiv^{S\text{-}\mathrm{dist}}\big(\oplus_{\beta<\alpha}R^{Y}_{\mathcal{T}_{\beta}}\big)_{Y,\mathrm{ind}}.\]

\end{enumerate}
We will prove the following: for any finite subset $F$ of $\mathbb{N}_0$, letting $G = \{0\}\cup\{k+1:k\in F\}$,
\begin{equation}
\label{showing these are really BRS spaces eq1}
Y_G = \langle h_{[0,1)}\rangle + T_{[0,1/2)}(Y_F) + T_{[1/2,1)}(Y_F).
\end{equation}
Using \eqref{showing these are really BRS spaces eq1}, \cref{showing these are really BRS spaces proof a} is a rather straightforward verification based on \Cref{disjointly branching tree operations} \ref{disjointly branching tree operations a} and \Cref{BRS definition trees}. \Cref{showing these are really BRS spaces proof b} is a similar verification using the corresponding definitions. It, therefore, suffices to prove \eqref{showing these are really BRS spaces eq1}. Because the dimensions of both sides of \eqref{showing these are really BRS spaces eq1} are equal, it suffices to show that the right side is included in the left. Because $0\in G$, we have $h_{[0,1)} = r_0\in Y_G$. It is enough to show that $T_{[0,1/2)}Y_F\subset Y_G$, since the argument for $T_{[1/2,1)}Y_F\subset Y_G$ is identical. As $T_{[0,1/2)}$ is a homomorphism, it suffices to verify that $T_{[0,1/2)}r_k\in Y_G$ for each $k\in F$. Now, $T_{[0,1/2)}r_k = r_{k+1}\chi_{[0,1/2)}$ and this function is $\sigma_G$-measurable because $k+1\in G$, the set $[0,1/2)$ is $r_0$-measurable, and $0\in G$.

\label{rem:BRS-equals-tree-BRS}
  Note that in the above proof, specifically in \cref{showing these are really BRS spaces proof b}, the right-hand side can in fact be taken as the definition of $R_\alpha^{Y}$. This shows that, with appropriate choices at limit steps, one may ensure that for all $0 \leq \alpha < \omega_1$, we have $R_\alpha^{Y} = R_{\mathcal{T}_\alpha}^{Y}$. {
In particular, if $\alpha$ is a limit ordinal, we may assume that $R_{\mathcal{T}_\alpha}^{Y} = [(J^{\alpha}_\beta(R_{\mathcal{T}_\beta}^{Y}))_{\beta < \alpha}]$, where $J^{\alpha}_\beta\colon Y\to Y$ are (square function-) distributional embeddings with (square function-) independent ranges, given by $J^{\alpha}_\beta = J_{F^{\alpha}_\beta}$ for some sequence $(F^{\alpha}_\beta)_{\beta < \alpha}$ of pairwise disjoint subsets of~$\mathbb{N}_0$ (see \Cref{rem:faithful-embeddings}).}

\label{simple BRS basis}
Let $\mathcal{T}$ be a disjointly branching tree and let $k\in\cup\mathcal{T}$.
\begin{enumerate}[label=(\alph*),]

\item Denote by $F(k)$ the unique $F\in\mathcal{T}$ with maximum $k$ and define $h(k) = |F(k)|-1$.

\item For $I\in\mathcal{D}^{h(k)}$ define $b_I^k = b_I^{F(k)}$.

\end{enumerate}

\label{prop:basis-of-tree-space}
Let $X$ be a Haar system space and $Y = X^0$ or $H_X$. For any disjointly branching tree  $\mathcal{T}$,
\[R^{Y}_\mathcal{T} = \big[\big((b_I^k)_{I\in\mathcal{D}^{h(k)}}\big)_{k\in\cup\mathcal{T}}\big].\]

\label{tree BRS spaces include sum BRS spaces}
Let $X$ be a Haar system space. If $\mathcal{T}$ and $\mathcal{S}$ are isomorphic disjointly branching trees then
\[R_\mathcal{T}^{X^0} \equiv^{\mathrm{dist}}R_\mathcal{S}^{X^0}\text{ and }R_\mathcal{T}^{H_X} \equiv^{S\text{-}\mathrm{dist}}R_\mathcal{S}^{H_X}.\]

\label{boyd def}
For a Haar system space $X$, the lower and upper Boyd indices of $X$ are
\begin{align*}
p_X = \lim_{n\to\infty} \frac{n}{\log_2(\|T^{-1}_{[0,2^{-n})}\|)}\text{ and }q_X = \lim_{n\to\infty} \frac{n}{\log_2(\|T_{[0,2^{-n})}\|^{-1})},
\end{align*}
where the appearing operators are $T_{[0,2^{-n})}:X\to X$ and $T^{-1}_{[0,2^{-n})}:T_{[0,2^{-n})}(X)\to X$ from \Cref{def  compression}.

\phantom{a}
\label{boyd vs unconditionality}
\begin{enumerate}[label=(\alph*)]

\item\label{boyd vs unconditionality a} The Boyd indices are usually defined using ${[0,\theta)}$ with $\theta\to 0^+$ rather than the discretized limits involving ${[0,2^{-n})}$. This modification does not affect the indices (see, e.g., the \cite[page 131]{lindenstrauss:tzafriri:1979:partII}). Our formulation also accommodates the case $\|\cdot\|_X\asymp \|\cdot\|_\infty$, when $T_{[0,\theta)}$ may be ill-defined.

\item\label{boyd vs unconditionality c} By \cite[Theorem 2.c.6]{lindenstrauss:tzafriri:1979:partII}, the Haar system is an unconditional basis for $X$ if and only if $p_X,q_X\in(1,\infty)$.

\end{enumerate}

By \Cref{haar system unconditional in hardy} \ref{haar system unconditional in hardy b} and \Cref{boyd vs unconditionality} \ref{boyd vs unconditionality c}, $\|\cdot\|_X\asymp\|\cdot\|_{H_X}$ and therefore, it suffices to prove the statement for the latter norm. By \cite[Proposition~9.5, p.~243]{johnson:maurey:schechtman:tzafriri:1979}, Stein's inequality holds in $X$, i.e., there exists a constant $C$ such that, for any $f_1,\ldots,f_n$ in $X$ and filtration $\mathcal{B}_1,\ldots,\mathcal{B}_n$ we have
\[\Big\|\Big(\sum_{k=1}^n\big(\mathbb{E}(f_k|\mathcal{B}_k)\big)^2\Big)^{1/2}\Big\|_X \leq C\Big\|\Big(\sum_{k=1}^nf_k^2\Big)^{1/2}\Big\|_X.\]
We will prove that $P_\mathcal{T}$ has norm at most $C^2$.

We will define two total orders on $\cup\mathcal{T}$, ``$\preccurlyeq$'' and ``$\curlyeqprec$''. Let $m,n\in\cup\mathcal{T}$. We will write $m\preccurlyeq n$ if one of the following holds:
\begin{equation}
\begin{gathered}
F(m)\sqsubseteq F(n)\text{ or}\\
F(m)\text{ and }F(n)\text{ are ``$\sqsubseteq$'' incomparable and }\min(F(m)\setminus F(n))<\min(F(n)\setminus F(m)).
\end{gathered}
\end{equation}
On the other hand, we will write $m\curlyeqprec n$ if one of the following holds:
\begin{equation}
\begin{gathered}
F(m)\sqsubseteq F(n)\text{ or}\\
F(m)\text{ and }F(n)\text{ are ``$\sqsubseteq$'' incomparable and }\min(F(m)\setminus F(n))>\min(F(n)\setminus F(m)).
\end{gathered}
\end{equation}
While the transitivity of ``$\preccurlyeq$'' and ``$\curlyeqprec$'' is not entirely obvious, one can convince oneself with a visual representation.

For every $k\in\cup\mathcal{T}$, we let $A(k) = \{m\in\cup\mathcal{T}:m\preccurlyeq k\}$ and $B(k) =  \{m\in\cup\mathcal{T}:m\curlyeqprec k\}$. Some of these sets may be infinite, but $(A(k))_{k\in\cup\mathcal{T}}$ and $(B(k))_{k\in\cup\mathcal{T}}$ are chains of subsets of $\mathbb{N}_0$, such that, for all $k\in\cup\mathcal{T}$, $A(k)\cap B(k) = F(k)$. To conclude, for $g\in  \langle h_I : I\in \mathcal{D} \rangle \subset  H_X$,
\begin{align*}
\|P_\mathcal{T}g\|_{H_X} &= \Big\|\Big(\sum_{k\in\cup\mathcal{T}}\big(\mathbb{E}_{F(k)}\big(\mathbb{E}_k-\mathbb{E}_{k-1}\big)(g)\big)^2\Big)^{1/2}\Big\|_X\\
&= \Big\|\Big(\sum_{k\in\cup\mathcal{T}}\big(\mathbb{E}_{A(k)}\mathbb{E}_{B(k)}\big(\mathbb{E}_k-\mathbb{E}_{k-1}\big)(g)\big)^2\Big)^{1/2}\Big\|_X\\
&\leq C\Big\|\Big(\sum_{k\in\cup\mathcal{T}}\big(\mathbb{E}_{B(k)}\big(\mathbb{E}_k-\mathbb{E}_{k-1}\big)(g)\big)^2\Big)^{1/2}\Big\|_X
\leq C^2\Big\|\Big(\sum_{k\in\cup\mathcal{T}}\big(\big(\mathbb{E}_k-\mathbb{E}_{k-1}\big)(g)\big)^2\Big)^{1/2}\Big\|_X\\
&\leq C^2\|g\|_{H_X}.\qedhere
\end{align*}

In the space $X=L_p$, $1<p<\infty$, Stein's inequality holds with constant $p^{*\,(p^*-2)/(2p^*-2)} \le p^{*\,1/2}$, where $p^* = \max\{p,p/(p-1)\}$. This can be seen by tracking the proof of Stein's theorem, for example, in \cite[Proposition 9.5, p.~243]{johnson:maurey:schechtman:tzafriri:1979}. The argument is carried out for $1<p\leq 2$ and relies on Doob's maximal inequality \cite[Chapter VII.3, Theorem 3.4]{doob:1953}, which introduces the factor $p^*$, together with the vector-valued Riesz-Thorin interpolation theorem \cite[Theorem 2, p.~316]{benedek:panzone:1961}, which produces the exponent $\theta=(p^*-2)/(2p^*-2)$ chosen so that $1/2=(1-\theta)/p$. Consequently, in $H_p$ we obtain $\|P_\mathcal{T}\|_{H_p\to H_p} \leq p^{*\,(p^*-2)/(p^*-1)}\leq  p^*$, and in $L_p$, using \cite[Theorem 8.6]{AdamOse:2012},
\begin{equation}
\label{orthogonal projection norm bound in Lp}
\|P_\mathcal{T}\|_{L_p\to L_p} \leq (p^*-1)^2p^{*\,(p^*-2)/(p^*-1)} \leq p^{*\,3}.
\end{equation}
As $p^*\to \infty$, the ratio between the refined bound and the simpler bound converges to one. The special feature of the refined estimate is that it equals one when $p^*=2$. Independent of this distinction, the bound in \eqref{orthogonal projection norm bound in Lp} improve the estimate obtained in \cite[p.~222, bottom]{bourgain:rosenthal:schechtman:1981} by a factor of order $p^{*\,1/2}$, reflecting the elimination of a minor redundancy in the core argument.

For an arbitrary Haar system space $X$, with $p_X,q_X\in(1,\infty)$, the constant in Stein's inequality is not, a priori, determined solely by $p_X$ and $q_X$.

\label{complemented Y index def}
Let $X$ be a Haar system space, $Y = X^0$ or $H_X$, and $W$ be a separable Banach space. The complemented $Y$-index of $W$ is defined as follows:
\begin{equation*}
i_Y[W] = \left\{\begin{array}{ll}\omega_1&\text{ if, for some $C\geq 1$, } \mathscr{T}(Y,W,C)\text{ is ill-founded,}\\
\sup_{C\geq 1}o[\mathscr{T}(Y,W,C)]&\text{ otherwise.}\end{array}\right.
\end{equation*}

\label{thm:operators-AB-copy}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$, and suppose that $(\tilde{h}_I)_{I\in \mathcal{D}}$ is an $(\eta_I)_{I\in \mathcal{D}}$-faithful Haar system for some family of real numbers $0 \le\eta_I < 1$ such that
  \begin{equation}\label{eq:3}
    \sigma := \sum_{J\in \mathcal{D}} \eta_I < 1.
  \end{equation}
  Then the operators $A,B\colon Y\to Y$ given by
  \begin{equation}\label{eq:9}
    Bx = \sum_{I\in \mathcal{D}} \frac{\langle h_I, x \rangle}{|I|} \tilde{h}_I\qquad \text{and} \qquad
    Ax = \sum_{I\in \mathcal{D}} \frac{\langle \tilde{h}_I, x \rangle}{|\mathcal{B}_I^{*}|} h_I
  \end{equation}
  are well-defined and bounded, and they satisfy $AB = I_Y$. In particular, $(\tilde{h}_I)_{I\in \mathcal{D}}$ is equivalent to $(h_I)_{I\in \mathcal{D}}$ in $Y$, and $[\tilde{h}_I]_{I\in \mathcal{D}}$ is complemented in $Y$ by the projection $BA$.
  Moreover, we have $|\mathcal{B}_I^{*}| \ge (1-\sigma)|\mathcal{B}_{[0,1)}^{*}| |I|$ for all $I\in \mathcal{D}$.

\label{lem:close-to-diagonal-operator}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$, and let $(\tilde{h}_I)_{I\in \mathcal{D}}$ be a $(\eta_I)_{I\in \mathcal{D}}$-faithful Haar system for some $(\eta_I)_{I\in \mathcal{D}}$, with Haar supports $\mathcal{B}_I$. Suppose that $\sigma < 1$, where $\sigma$ is defined as in~\eqref{eq:3}. Moreover, let $\varepsilon > 0$, and let $(\varepsilon_{I,J})_{I,J\in \mathcal{D}}$ be a family of positive numbers such that
  \begin{equation}\label{eq:13}
    \sum_{I,J\in \mathcal{D}} \frac{\varepsilon_{I,J}}{|I| |J|} < \varepsilon.
  \end{equation}
  If $T\colon Y\to Y$ is a bounded linear operator and $|\langle \tilde{h}_I, T \tilde{h}_J \rangle|\le \varepsilon_{I,J}$ for all $I\ne J\in \mathcal{D}$, then the linear extension of $Dh_I = |\mathcal{B}_I^{*}|^{-1}\langle \tilde{h}_I, T \tilde{h}_I\rangle  h_I$, $I\in \mathcal{D}$,
  defines a bounded Haar multiplier on~$Y$ such that $\|ATB - D\| \le \varepsilon (1-\sigma)^{-1}|\mathcal{B}_{[0,1)}^{*}|^{-1}$, where $A,B$ are the associated operators from \Cref{thm:operators-AB-copy}.

For every $J\in \mathcal{D}$, we have
  \begin{equation*}
    \|(ATB - D) h_J\| = \Bigl\| \sum_{\substack{I\in \mathcal{D}\\ I\ne J}} \frac{\langle \tilde{h}_I, T \tilde{h}_J \rangle}{|\mathcal{B}_I^{*}|}h_I \Bigr\|
    \le \sum_{\substack{I\in \mathcal{D}\\ I\ne J}} \frac{|\langle \tilde{h}_I, T \tilde{h}_J \rangle|}{|\mathcal{B}_I^{*}|} \|h_I\|
    \le \sum_{\substack{I\in \mathcal{D}\\ I\ne J}} \frac{\varepsilon_{I,J}}{|\mathcal{B}_I^{*}|}.
  \end{equation*}
  For every finite linear combination $x = \sum_{J\in \mathcal{D}} a_Jh_J\in X$, we have $|a_J| = |J|^{-1} |\langle h_J,x \rangle|\le |J|^{-1}\|x\|$ for all $J$ (note that $\|h_J\|_{Y^{*}}\le 1$ by \Cref{pro:HSHS-1d}~\ref{pro:HSHS-1d:v}). Thus, we obtain
  \begin{equation*}
    \|(ATB - D)x\|
    \le \sum_{J\in \mathcal{D}} |a_J|\|(ATB - D)h_J\|
    \le \|x\| \sum_{I,J\in \mathcal{D}} \frac{\varepsilon_{I,J}}{|\mathcal{B}_I^{*}| |J|}
    \le \frac{\varepsilon \|x\|}{(1-\sigma)|\mathcal{B}_{[0,1)}^{*}|},
  \end{equation*}
  where we used~\eqref{eq:13} and the last statement of \Cref{thm:operators-AB-copy}.

Let $\mathcal{A}\subset \mathcal{D}$ be a collection of dyadic intervals.
  By $\limsup \mathcal{A}$ we denote the set of all points $t\in [0,1)$ which are contained in infinitely many intervals $I\in \mathcal{A}$.
  Moreover, we define
  \begin{equation*}
    \mathcal{G}_0(\mathcal{A}) = \{ I\in \mathcal{D} : I \text{ is maximal with respect to inclusion} \}
  \end{equation*}
  and, for $n\ge 1$,
  \begin{equation*}
    \mathcal{G}_n(\mathcal{A}) = \mathcal{G}_0\Bigl( \mathcal{A}\setminus \bigcup_{k=0}^{n-1}\mathcal{G}_k(\mathcal{A}) \Bigr).
  \end{equation*}
  Note that the ``generations'' $\mathcal{G}_n(\mathcal{A})$ are pairwise disjoint collections and each of them consists of pairwise disjoint intervals. If $n\ge 1$ and $I\in \mathcal{G}_n(\mathcal{A})$, then there exists a unique interval $J\in \mathcal{G}_{n-1}(\mathcal{A})$ such that $I\subset J^+$ or $I\subset J^-$. In particular, $\mathcal{G}_0(\mathcal{A})^{*}\supset \mathcal{G}_1(\mathcal{A})^{*}\supset \cdots$.
  See \Cref{fig:generations} for an example.
  Also note that $\mathcal{G}_n(\mathcal{A})^{*}$ is the set of points in $[0,1)$ contained in at least $n+1$ intervals from $\mathcal{A}$, hence the intersection of all sets $\mathcal{G}_n(\mathcal{A})^{*}$ is $\limsup(\mathcal{A})$.

\label{lem:choice-of-B_I}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$. Suppose that the sequence of Rademacher functions is weakly null in $Y$. Let $\mathcal{A}\subset \mathcal{D}$, let $S = \limsup(\mathcal{A})$, and let $\Gamma \subset [0,1)$ be a finite union of dyadic intervals such that $|\Gamma \cap S| > (1 - \tilde{\eta})|\Gamma|$ for some $0 < \tilde{\eta} < 1$. Moreover, let $\mathcal{E}\subset \mathcal{D}$, $F\subset Y$ and $G\subset Y^{*}$ be finite, and let $\eta,\varepsilon > 0$. Then there exists a finite collection $\mathcal{B}\subset \mathcal{A}\setminus \mathcal{E}$ of pairwise disjoint dyadic intervals with the following properties:
\begin{enumerate}[label=(\alph*),]
    \item\label{lem:choice-of-B_I:a} $\mathcal{B}^{*}\subset \Gamma$
    \item\label{lem:choice-of-B_I:b} $|\mathcal{B}^{*}| > (1 - \tilde{\eta}) |\Gamma|$
    \item\label{lem:choice-of-B_I:c} $|\mathcal{B}^{*}\cap S| > (1 - \eta) |\mathcal{B}^{*}|$
    \item\label{lem:choice-of-B_I:d} For every choice of signs $\theta\in \{ \pm 1 \}^{\mathcal{B}}$, the function $\tilde{h} = \sum_{K\in \mathcal{B}} \theta_Kh_K$ satisfies
  \begin{equation}
    \max_{g\in G} |\langle g, \tilde{h} \rangle| < \varepsilon
    \qquad \text{and} \qquad
    \max_{f\in F} |\langle \tilde{h}, f \rangle| < \varepsilon.
  \end{equation}
  \end{enumerate}

The collection $\mathcal{C} = \{ K\in \mathcal{A} : K\subset \Gamma \}$ satisfies $\limsup(\mathcal{C}) = \Gamma \cap S$, so for all $n\in \mathbb{N}_0$, we have
  \begin{equation}\label{eq:1}
    |\mathcal{G}_n(\mathcal{C})^{*}| \ge |\limsup \mathcal{C}| = |\Gamma \cap S| > (1 - \tilde{\eta})|\Gamma|.
  \end{equation}
  Moreover, for all sufficiently large $n$, we have $|\mathcal{G}_n(\mathcal{C})\cap S| > (1 - \eta) |\mathcal{G}_n(\mathcal{C})$.
  If $Y = X^0$, then by \cite[Lemma~4.3]{lechner:motakis:mueller:schlumprecht:2022}, there exists $K_0\in \mathcal{D}$ such that for any finite collection $\mathcal{B}\subset \mathcal{D}$ of pairwise disjoint dyadic intervals with $K\ge K_0$ for all $K\in \mathcal{B}$ and every choice of signs $\theta\in \{ \pm 1 \}^{\mathcal{B}}$, we have
 \begin{equation}\label{eq:2}
    \max_{g\in G}\,  \Bigl| \Bigl\langle g, \sum_{K\in \mathcal{B}} \theta_Kh_K \Bigr\rangle \Bigr| <  \varepsilon
    \qquad \text{and} \qquad
    \max_{f\in F}\,  \Bigl| \Bigl\langle \sum_{K\in \mathcal{B}} \theta_Kh_K, f \Bigr\rangle \Bigr| <  \varepsilon.
  \end{equation}
  The proof in~\cite{lechner:motakis:mueller:schlumprecht:2022} also carries over to the case $Y = H_X$.
  By choosing $n$ large enough, we may assume that $K \ge K_0$ for all $K\in \mathcal{G}_n(\mathcal{C})$ and that $\mathcal{G}_n(\mathcal{C})\subset \mathcal{A}\setminus \mathcal{E}$. Now we take $\mathcal{B}$ to be a finite subcollection of $\mathcal{G}_n(\mathcal{C})$ which still satisfies $|\mathcal{B}^{*} \cap S| > (1 - \eta) |\mathcal{B}^{*}|$ as well as $|\mathcal{B}^{*}| > (1 - \tilde{\eta}) |\Gamma|$. Then properties~\ref{lem:choice-of-B_I:a}--\ref{lem:choice-of-B_I:c} are satisfied, and~\ref{lem:choice-of-B_I:d} follows from~\eqref{eq:2}.

\label{thm:factorization-property++}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$, and suppose that the Haar system is unconditional in~$Y$. Let
  $T\colon Y\to Y$ be a given operator, and suppose that there exists $\delta > 0$ such that if
  \begin{equation*}
    \mathcal{A} = \{ I\in \mathcal{D} : |\langle h_I, T h_I \rangle| \ge \delta |I| \},
  \end{equation*}
  then $\limsup \mathcal{A}$ has positive Lebesgue measure.
  Then the identity on $Y$ factors through $T$. In particular, there exists a subspace $Z$ of $Y$ with $Z$ isomorphic to $Y$, $T|_Z$ an isomorphism, and $T(Z)$ complemented in $Y$.

Define
  \begin{equation*}
    \mathcal{A}_1 = \{ I\in \mathcal{D} : \langle h_I, T h_I \rangle \ge \delta |I| \}
     \qquad\text{and}\qquad
    \mathcal{A}_2 = \{ I\in \mathcal{D} : \langle h_I, T h_I \rangle \le -\delta |I| \}.
  \end{equation*}
  Then $\mathcal{A}_1\cup \mathcal{A}_2 = \mathcal{A}$, so either $\limsup \mathcal{A}_1$ or $\limsup \mathcal{A}_2$ has positive measure. We assume that $|\limsup \mathcal{A}_1| > 0$ (otherwise, replace $T$ by $-T$), and put $S = \limsup \mathcal{A}_1$. Let $(\eta_I)_{I\in \mathcal{D}}$ be a family in $[0,1)$ with $\sigma < 1$, where $\sigma$ is defined as in~\eqref{eq:3}. We will construct an $(\eta_I)_{I\in \mathcal{D}}$-faithful Haar system from the Haar functions $(h_K)_{K\in \mathcal{A}_1}$ which almost diagonalizes~$T$. To this end, we also fix $0 < \varepsilon < \delta C^{-1}(1-\sigma)|S|/2$
  (where $C$ is the unconditional constant of the Haar system in $Y$) and a family $(\varepsilon_{I,J})_{I,J\in \mathcal{D}}$ of positive numbers satisfying~\eqref{eq:13}. For each $I\in \mathcal{D}$, we choose $\varepsilon_I > 0$ such that $\varepsilon_I < \max(\varepsilon_{I,J},\varepsilon_{J,I})$ for all $J\in \mathcal{D}$ with $J < I$.
  First, we explain how the Haar supports $\mathcal{B}_I$ of $\tilde{h}_I$ are defined:
  \begin{itemize}
    \item If $I = [0,1)$, we apply \Cref{lem:choice-of-B_I} to $\mathcal{A} = \mathcal{A}_1$, $\Gamma = [0,1)$, $\tilde{\eta} = 1 - |S|/2$, $\mathcal{E} = F = G = \emptyset$, $\eta = \eta_{[0,1)}/2$, and $\varepsilon = 1$. This yields a finite collection $\mathcal{B}_{[0,1)}\subset \mathcal{A}_1$ with $|\mathcal{B}_{[0,1)}^{*}| \ge |S|/2$ and $|\mathcal{B}_{[0,1)}^{*}\cap S| > (1 - \eta_{[0,1)}/2)|\mathcal{B}_{[0,1)}^{*}|$.
    \item If $I\ne [0,1)$, we assume that for every $J<I$, we have already constructed $\mathcal{B}_J$ and $\tilde{h}_J$ such that $|\mathcal{B}_J^{*}\cap S| >  (1-\eta_J/2)|\mathcal{B}_J^{*}|$.
          Put $\Gamma = [\tilde{h}_{\pi(I)} = \varepsilon(I)]$. Then the above inequality implies $|\Gamma\cap S| > (1-\eta_{\pi(I)})|\Gamma|$.
          Now we apply \Cref{lem:choice-of-B_I} to $\mathcal{A} = \mathcal{A}_1$, $\Gamma$ as defined above, $\tilde{\eta} = \eta_{\pi(I)}$, $\mathcal{E} = \bigcup_{J < I}\mathcal{B}_J$, $F = \{ T \tilde{h}_J : J < I \}$, $G = \{ T^{*} \tilde{h}_J : J < I \}$, $\eta = \eta_I/2$, and $\varepsilon = \varepsilon_I$. This yields a finite collection $\mathcal{B}_I\subset \mathcal{A}_1\setminus \bigcup_{J < I}\mathcal{B}_J$ with $\mathcal{B}_I^{*}\subset \Gamma$ such that $|\mathcal{B}_I^{*}\cap S| > (1-\eta_I/2)|\mathcal{B}_I^{*}|$ as well as $|\mathcal{B}_I^{*}| > (1-\eta_{\pi(I)}) \cdot \frac{1}{2}|\mathcal{B}_{\pi(I)}^{*}|$. Hence, conditions~\ref{cond:faithful-i-copy},~\ref{cond:faithful-ii-copy} of \Cref{dfn:faithful-HS} are indeed satisfied. Moreover, for every choice of signs $\theta\in \{ \pm 1 \}^{\mathcal{B}_I}$, the function $\tilde{h}_I = \sum_{K\in \mathcal{B}_I} \theta_Kh_K$ satisfies
  \begin{equation}\label{eq:10}
    \max_{J\in \mathcal{D} : J<I} |\langle \tilde{h}_J, T \tilde{h}_I \rangle| < \varepsilon_I
    \qquad \text{and} \qquad
    \max_{J\in \mathcal{D} : J<I} |\langle \tilde{h}_I, T \tilde{h}_J \rangle| < \varepsilon_I.
  \end{equation}
\end{itemize}


  After constructing $\mathcal{B}_I$ for a given $I\in \mathcal{D}$, we choose the signs $\theta\in \{ \pm 1 \}^{\mathcal{B}_I}$ uniformly at random and note that since $\mathcal{B}_I\subset \mathcal{A}_1$, the randomized function $\tilde{h}_I = \sum_{K\in \mathcal{B}_I} \theta_Kh_K$ satisfies
  \begin{equation*}
    \mathbb{E}_{\theta\in \{ \pm 1 \}^{\mathcal{B}_I}} \langle \tilde{h}_I, T \tilde{h}_I \rangle = \sum_{K\in \mathcal{B}_I} \langle h_K, T h_K \rangle \ge \delta |\mathcal{B}_I^{*}|.
  \end{equation*}
  Hence, we can choose at least one sign vector $\theta\in \{ \pm 1 \}^{\mathcal{B}_I}$ such that the resulting function $\tilde{h}_I$ satisfies
  \begin{equation}\label{eq:11}
    \langle \tilde{h}_I, T \tilde{h}_I \rangle \ge \delta |\mathcal{B}_I^{*}|.
  \end{equation}
  Having constructed the $(\eta_I)_{I\in \mathcal{D}}$-faithful Haar system $(\tilde{h}_I)_{I\in \mathcal{D}}$, we now use \Cref{thm:operators-AB-copy}, \eqref{eq:10}, and \Cref{lem:close-to-diagonal-operator} to conclude that the associated operators $A,B$ and the Haar multiplier $D\colon Y\to Y$ defined by
  \begin{equation*}
    Dh_I = \frac{\langle \tilde{h}_I, T \tilde{h}_I \rangle}{|\mathcal{B}_I^{*}|} h_I,\qquad I\in \mathcal{D},
  \end{equation*}
  are bounded and satisfy $\|ATB - D\|\le \varepsilon(1-\sigma)^{-1}|\mathcal{B}_{[0,1)}^{*}|^{-1} < \delta C^{-1}$. Moreover, by~\eqref{eq:11}, $D$ has $\delta$-large positive entries, so its inverse satisfies $\|D^{-1}\| \le \delta^{-1}C$.
  Thus, $\|D^{-1}ATB - I_Y\|\le \varepsilon \delta^{-1} C < 1$, so $D^{-1}ATB$ is invertible, and the identity $I_Y$ factors through $T$. The subspace $Z$ can be chosen as $B(Y)$.

\label{cor:primary-factorization-property}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$. Suppose that the Haar system is unconditional in~$Y$.
  Then $Y$ has the primary factorization property.

\label{lem:sublemma-1-copy}
  Let $X$ be a Haar system space and $Y = X^0$ or $H_X$. Suppose that the Haar system is unconditional in~$Y$ and that $Y$ is isomorphic, via an embedding $\iota\colon Y\to Z$, to a complemented subspace of a Banach space $Z$ with an unconditional Schauder decomposition $(Z_i)_{i=1}^{\infty}$. Let $U\colon Z\to Y$ be an operator with $U\iota = I_Y$. Moreover, let $Q_i\colon Z\to Z_i$ denote the natural projections associated with $(Z_i)_{i=1}^{\infty}$, and for $F\subset \mathbb{N}$, put $Q_F = \sum_{i\in F} Q_i$. Assume that no $Z_i$ contains a complemented subspace isomorphic to $Y$. Then, for every $n\in \mathbb{N}$, the collection
  \begin{equation*}
    \mathcal{A} = \{ I\in \mathcal{D} : \langle h_I, UQ_{[n,\infty)}\iota h_I\rangle > \tfrac{1}{2} |I| \}
  \end{equation*}
  satisfies $|\limsup \mathcal{A}| = 1$.

Suppose that $|\limsup \mathcal{A}| < 1$. Let $n\in \mathbb{N}$, and put
  \begin{equation*}
    \mathcal{B} = \{ I\in \mathcal{D} : \langle h_I, UQ_{[1,n)}\iota h_I\rangle  \ge \tfrac{1}{2} |I| \}.
  \end{equation*}
  Then, since $U(Q_{[1,n)} + Q_{[n,\infty)})\iota = I_Y$, we see that $\mathcal{A}\cup \mathcal{B} = \mathcal{D}$, and hence, $\limsup\mathcal{A}\cup \limsup\mathcal{B} = [0,1)$. Since $|\limsup \mathcal{A}| < 1$, this implies $|\limsup\mathcal{B}| > 0$. Hence, $T = UQ_{[1,n)}\iota$ satisfies the hypotheses of \Cref{thm:factorization-property++}. Thus, there is a subspace $E$ of $Y$ with $E$ isomorphic to $Y$, $T|_E = UQ_{[1,n)}\iota|_E$ an isomorphism, and $T(E)$ complemented in $Y$. It follows easily that $Q_{[1,n)}\iota(E)$ is complemented in $Z$ and hence in $Q_{[1,n)}(Z)\simeq  Z_1 \oplus \dots \oplus Z_{n-1}$: Indeed, if $P$ is a projection from~$Y$ onto $T(E)$, then a projection from~$Z$ onto $Q_{[1,n)}\iota(E)$ is given by $\Pi = Q_{[1,n)}\iota(T|_E)^{-1}PU$.
  But this implies that $Y$ is isomorphic to a complemented subspace of $Z_1\oplus \dots\oplus Z_{n-1}$, so by \Cref{cor:primary-factorization-property} and \Cref{prop:pfp-complemented-subspace-direct-sum}, $Y$ is isomorphic to a complemented subspace of $Z_i$ for some~$i$, contradicting the hypothesis. Hence, we must have $|\limsup \mathcal{A}| = 1$.

Assume that $Y$ is isomorphic, via an embedding $\iota\colon Y\to Z$, to a complemented subspace of $Z$, and let $U\colon Z\to Y$ be an operator with $U\iota = I_Y$. Let $C$ denote the unconditional constant of the basis $(h_I)_I$ of $Y$. Let $(Z_i)_{i=1}^{\infty}$ be an unconditional decomposition of $Z$ with associated projections $(Q_i)$. Suppose that there is no $i$ with $Y$ isomorphic to a complemented subspace of~$Z_i$. Our goal is to construct a block sequence of the spaces $Z_i$ which is equivalent to the Haar system in $Y$ and has closed linear span complemented in $Z$.

To this end, we will construct a ``blocking'' of the decomposition $(Z_i)_{i=1}^{\infty}$, resulting in a new decomposition with projections $\bar{Q}_k$, $k\in \mathbb{N}$. To be precise, we will choose integers $1 = m_0 < m_1 < m_2 < \dots$ and put $\bar{Q}_k = Q_{[m_{k-1},m_k)} = \sum_{l = m_{k-1}}^{m_k - 1} Q_l$ for $k\in \mathbb{N}$. This defines an unconditional Schauder decomposition of $Z$ with the same unconditional constant. We will relabel the projections as $(\bar{Q}_I)_{I\in \mathcal{D}}$ via the usual bijection between $\mathbb{N}$ and $\mathcal{D}$.
At the same time, we will construct an almost faithful Haar system $(\tilde{h}_I)_{I\in \mathcal{D}}$ and an unconditional Schauder decomposition of $Y$ with associated projections $(P_I)_{I\in \mathcal{D}}$, with $P_I \tilde{h}_J = \delta_{I,J} \tilde{h}_J$ for all $I,J\in \mathcal{D}$, such that:
\begin{enumerate}[label=(\alph*),]
  \item\label{cond:i} $(\tilde{h}_I)_{I\in \mathcal{D}}$ satisfies the assumptions of \Cref{thm:operators-AB-copy}, and thus, it is equivalent to the Haar system $(h_I)_{I\in \mathcal{D}}$ in $Y$ and $[\tilde{h}_I]_{I\in \mathcal{D}}$ is complemented in $Y$.
  \item\label{cond:ii} $\langle \tilde{h}_I, U \bar{Q}_I \iota\tilde{h}_I \rangle > \frac{1}{2}|\mathcal{B}_I^{*}|$ for all $I\in \mathcal{D}$, where $\mathcal{B}_I$ is the Haar support of $\tilde{h}_I$.
  \item\label{cond:iii} $(\tilde{h}_I)_{I\in \mathcal{D}}$ ``almost diagonalizes'' the operator $UV$, where $V = \sum_I \bar{Q}_I \iota P_I$.
\end{enumerate}
To this end, fix a family $(\eta_I)_{I\in \mathcal{D}}$ in $[0,1)$ such that $\sigma < 1$, where $\sigma$ is defined as in~\eqref{eq:3}.
We also fix $0 < \varepsilon <  C^{-1}(1-\sigma)/2$ and a family $(\varepsilon_{I,J})_{I,J\in \mathcal{D}}$ of positive numbers satisfying~\eqref{eq:13}. For each $I\in \mathcal{D}$, we choose $\varepsilon_I > 0$ such that $\varepsilon_I < \max(\varepsilon_{I,J},\varepsilon_{J,I})$ for all $J\in \mathcal{D}$ with $J < I$.
Now let $k\in \mathbb{N}$, and let $I$ be the $k$th dyadic interval in the usual enumeration of $\mathcal{D}$.\medskip

\noindent\textbf{Case $k = 1$.}
If $k = 1$, i.e., $I =  [0,1)$, we simply put $\mathcal{B}_{[0,1)} = \{ [0,1) \}$ and $\tilde{h}_{[0,1)} = h_{[0,1)}$. Then $h_{[0,1)} = U\iota h_{[0,1)} = \lim_{n\to \infty} U Q_{[1,n)}\iota h_{[0,1)}$. So we can choose $m_1 > 1$ such that $\|UQ_{[1,m_1)}\iota h_{[0,1)} - h_{[0,1)}\| < 1/2$, hence $\langle h_{[0,1)}, U \bar{Q}_{[0,1)}\iota h_{[0,1)} \rangle > 1/2$, where $\bar{Q}_{[0,1)}=Q_{[1,m_1)}$ (note that $\|h_{[0,1)}\|_{Y^{*}} = 1$).\medskip

\noindent\textbf{Case $k > 1$.} Assume that we have already chosen $m_0 < m_1 < \dots < m_{k-1}$ and constructed $\tilde{h}_J$ for all $J<I$. Moreover, put $\Gamma = [\tilde{h}_{\pi(I)}= \varepsilon(I)]$. We will use the abbreviation $n = m_{k-1}$.
  Now define
  \begin{equation*}
    \mathcal{A} = \{ K\in \mathcal{D} : \langle h_K, UQ_{[n,\infty)}\iota h_K \rangle > \tfrac12 |K| \}.
  \end{equation*}
  Since we assumed that there is no $i$ with $Y$ isomorphic to a complemented subspace of $Z_i$, \Cref{lem:sublemma-1-copy} implies that $|\limsup (\mathcal{A})| = 1$. Now we apply \Cref{lem:choice-of-B_I} to $\mathcal{A}$ and $\Gamma$ as defined above, $\tilde{\eta} = \eta_{\pi(I)}$, $\mathcal{E} = \bigcup_{J < I} \mathcal{B}_J$, $F = \{ U \bar{Q}_J \iota\tilde{h}_J : J < I \}$, $G = \{ (UQ_{[n,\infty)}\iota)^{*} \tilde{h}_J : J < I \}$, $\eta = 1$, and $\varepsilon = \varepsilon_I$. This yields a finite collection $\mathcal{B}_I\subset \mathcal{A}\setminus \mathcal{E}$ with $\mathcal{B}_I^{*}\subset \Gamma$ and $|\mathcal{B}_I^{*}| \ge (1-\eta_{\pi(I)})|\Gamma| = (1-\eta_{\pi(I)})\cdot \frac12 |\mathcal{B}_{\pi(I)}^{*}|$. Hence, conditions~\ref{cond:faithful-i-copy},~\ref{cond:faithful-ii-copy} of \Cref{dfn:faithful-HS} are indeed satisfied. Moreover, for every choice of signs $\theta\in \{ \pm 1 \}^{\mathcal{B}_I}$, the function $\tilde{h}_I = \sum_{K\in \mathcal{B}_I} \theta_Kh_K$ satisfies
  \begin{equation}\label{eq:14}
    \max_{J\in \mathcal{D} : J<I} |\langle \tilde{h}_J, UQ_{[n,\infty)}\iota\tilde{h}_I \rangle| < \varepsilon_I
    \qquad \text{and} \qquad
    \max_{J\in \mathcal{D} : J<I} |\langle \tilde{h}_I, U \bar{Q}_J \iota\tilde{h}_J \rangle| < \varepsilon_I.
  \end{equation}


  Next, since $\mathcal{B}_I\subset  \mathcal{A}$, as in \Cref{thm:factorization-property++}, we can find a sign vector $\theta\in \{ \pm 1 \}^{\mathcal{B}_I}$ such that $\tilde{h}_I = \sum_{K\in \mathcal{B}_I} \theta_Kh_K$ satisfies
  \begin{equation}\label{eq:15}
    \langle \tilde{h}_I, UQ_{[n,\infty)}\iota\tilde{h}_I \rangle > \tfrac12  |\mathcal{B}_I^{*}|.
  \end{equation}


  Finally, since $Q_{[n,\infty)}y = \lim_{m\to \infty} Q_{[n,m)}y$ for all $y\in Z$, we can choose $m_k\in \mathbb{N}$ sufficiently large such that $m_k > n = m_{k-1}$ and such that after putting $\bar{Q}_I = Q_{[m_{k-1},m_k)}$, we still have
  \begin{equation}\label{eq:16}
    \max_{J\in \mathcal{D} : J<I} |\langle \tilde{h}_J, U \bar{Q}_I \iota\tilde{h}_I \rangle| < \varepsilon_I
    \qquad \text{and} \qquad
    \max_{J\in \mathcal{D} : J<I} |\langle \tilde{h}_I, U \bar{Q}_J \iota\tilde{h}_J \rangle| < \varepsilon_I
  \end{equation}
  as well as
  \begin{equation}\label{eq:17}
    \langle \tilde{h}_I, U \bar{Q}_I \iota\tilde{h}_I \rangle > \tfrac12  |\mathcal{B}_I^{*}|,
  \end{equation}
  cf.~\eqref{eq:14} and~\eqref{eq:15}. This completes the construction of the system $(\tilde{h}_I)_{I\in \mathcal{D}}$ and the projections $(\bar{Q}_I)_{I\in \mathcal{D}}$. Finally, choose a partition of $\mathcal{D}$ into finite subcollections $\mathcal{E}_I\subset \mathcal{D}$, $I\in \mathcal{D}$, such that $\mathcal{B}_I\subset \mathcal{E}_I$ for all $I\in \mathcal{D}$. The collections $\mathcal{E}_I$ define a $C$-unconditional Schauder decomposition of $Y$ with associated projections $P_I$ such that $P_I \tilde{h}_J = \delta_{I,J} \tilde{h}_J$ for all $I,J\in \mathcal{D}$.

  Next, consider the operator $V = \sum_I \bar{Q}_I \iota P_I$ and note that $V$ is bounded according to \Cref{lem:1.3}. Observe that $V \tilde{h}_I = \bar{Q}_I \iota\tilde{h}_I$ for all $I\in \mathcal{D}$. Hence, we may replace both $U \bar{Q}_I \iota$ and $U \bar{Q}_J \iota$ by the operator $UV$ in~\eqref{eq:16} and~\eqref{eq:17} (which also holds for $I = [0,1)$). Thus, we can apply \Cref{lem:close-to-diagonal-operator}, which implies that the Haar multiplier $D$ defined by
  \begin{equation*}
    D h_I = \frac{\langle \tilde{h}_I, UV \tilde{h}_I \rangle}{|\mathcal{B}_I^{*}|} h_I,\qquad I\in \mathcal{D},
  \end{equation*}
  is bounded on $Y$ and satisfies $\|AUVB - D\| < \varepsilon (1-\sigma)^{-1} < C^{-1}/2$, where $A,B$ are the operators associated with $(\tilde{h}_I)_{I\in \mathcal{D}}$. Moreover, by~\eqref{eq:17}, the entries of $D$ are larger than $1/2$, which implies that $D^{-1}$ is bounded and satisfies $\|D^{-1}\|\le 2C$. Hence, we have $\|D^{-1}AUVB - I_Y\| < 1$, so there exists an operator $R$ on $Y$ such that $I_Y = RD^{-1}AUVB$. This implies that $(VBh_I)_{I\in \mathcal{D}} = (\bar{Q}_I \iota\tilde{h}_I)_{I\in \mathcal{D}}$ is equivalent to $(h_I)_{I\in \mathcal{D}}$ in $Y$, and its closed linear span is complemented in $Z$ by the projection $VBRD^{-1}AU$.

Let $X$ be a Haar system space that satisfies the assumptions of \Cref{thm:alternatives-ri} or \Cref{thm:alternatives-hardy}, and let $Y = X^0$ or $H_X$, respectively. Then the Haar system is unconditional in $Y$, and all spaces $R_{\mathcal{T}_\alpha}^{Y}$, $\alpha < \omega_1$, are complemented $Y$ (if $Y = X^0$, this follows from \Cref{prop:complementation}).
\begin{itemize}[leftmargin=1.5em, labelsep=1.5em, align=left, itemsep=0.5em]
  \item[\ref{thm:alternatives:b}$\Longrightarrow$\ref{thm:alternatives:c}.] This is immediate.
  \item[\ref{thm:alternatives:c}$\Longrightarrow$\ref{thm:alternatives:b}.]
        Suppose that~\ref{thm:alternatives:c} is true. We will prove that $R_\omega^{Y}$ contains a complemented copy of~$Y$. Then, as $R_\omega^{Y}$ also embeds complementably into $R_\beta^{Y}$ for all $\omega \le \beta < \omega_1$ and both~$Y$ and~$R_\beta^{Y}$ are isomorphic to their squares (see \Cref{prop:isomorphic-to-square}, and \Cref{prop:R-alpha-Y-0-isomorphic-to-its-square}), we obtain~\ref{thm:alternatives:b} using Pe{\l}czy\'nski's decomposition method.

  Let $\alpha$ be the smallest countable ordinal such that $R_\alpha^{Y}$ contains a complemented copy of~$Y$. Clearly, $\alpha$ must be infinite, and it cannot be a successor ordinal: If $\alpha = \beta + 1$, we would have $R_\alpha^{Y} = (R_\beta^{Y} \oplus R_\beta^{Y})_{\mathrm{disj},Y}^+ \simeq R_\beta^{Y} \oplus R_\beta^{Y} \oplus \mathbb{R}$, so by \Cref{cor:primary-factorization-property} and \Cref{prop:pfp-complemented-subspace-direct-sum}, the space~$R_\beta^{Y}$ would also contain a complemented copy of $Y$, contradicting the minimality of~$\alpha$.
        Hence, $\alpha$ is a limit ordinal, and by \Cref{showing these are really BRS spaces}, we have $R_\alpha^{Y}\equiv R_{\mathcal{T}_\alpha}^{Y}$. Moreover, by \Cref{rem:BRS-equals-tree-BRS}, the tree $\mathcal{T}_\alpha$ may be chosen such that
        \begin{equation*}
         R_{\mathcal{T}_\alpha}^{Y} = [(J^{\alpha}_\beta(R_{\mathcal{T}_\beta}^{Y}))_{\beta < \alpha}]
       \end{equation*}
        for a suitable choice of (square function-) distributional embeddings $J^{\alpha}_\beta\colon Y\to Y$, $\beta < \alpha$, with (square function-) independent ranges. The spaces $J^{\alpha}_\beta(R_{\mathcal{T}_\beta}^{Y})$, $\beta < \alpha$, form an unconditional Schauder decomposition of $R_{\mathcal{T}_\alpha}^{Y}$. Since none of them contains a complemented copy of $Y$, \Cref{thm:1.1} implies that a block basic sequence $(x_n)_{n=1}^{\infty}$ of the spaces $J^{\alpha}_\beta(R_{\mathcal{T}_\beta}^{Y})$, $\beta < \alpha$, is equivalent to the Haar system in $Y$ and has closed linear span complemented in $R_{\mathcal{T}_\alpha}^{Y}$. In passing, we note that this implies~\ref{thm:alternatives:d} if $Y = X^0$, since $R_{\mathcal{T}_\alpha}^{Y}$ is in turn complemented in $Y$.

        Now write
  \begin{equation*}
    x_n = \sum_{\beta \in \sigma_n}  y_\beta,\qquad n\in \mathbb{N},
  \end{equation*}
  where the sets $\sigma_n$ are pairwise disjoint finite sets of ordinals smaller than $\alpha$ and $y_\beta = J^{\alpha}_\beta z_\beta$ for some $z_\beta \in R_{\mathcal{T}_\beta}^{Y}$. By the principle of small perturbations, we may assume that each vector~$z_\beta$ is a finite linear combination of blocks of the standard Haar system (note that these are dense in $R_{\mathcal{T}_\beta}^{Y}$ by \Cref{prop:basis-of-tree-space}), while $[x_n]_{n\in \mathbb{N}}$ is still complemented in~$R_{\mathcal{T}_\alpha}^{Y}$ by a projection $P\colon R_{\mathcal{T}_\alpha}^{Y}\to R_{\mathcal{T}_\alpha}^{Y}$. In particular, there exist pairwise distinct numbers $k(\beta)\in \mathbb{N}$, $\beta < \alpha$, such that $z_\beta\in Y_{k(\beta) - 1} = R_{k(\beta)}^{Y}$ for all~$\beta$.
  Now recall that $R_\omega^{Y} = [(J^{\omega}_k(R_k^{Y}))_{k=0}^{\infty} ]$ for certain (square function-) distributional embeddings $J_k^{\omega}$ with independent ranges, and define the operator $U\colon [y_\beta]_{\beta < \alpha} \to R_\omega^{Y}$ by
  \begin{equation*}
    Uy_\beta = \tilde{y}_\beta := J_{k(\beta)}^{\omega}z_\beta,\qquad \beta < \alpha.
  \end{equation*}
  Then $U$ is an isometry. In particular, the sequence $(\tilde{x}_n)_{n=1}^{\infty}$ defined by
  \begin{equation*}
    \tilde{x}_n = U x_n = \sum_{\beta \in \sigma_n} \tilde{y}_\beta \in R_\omega^{Y},\qquad  n\in \mathbb{N},
  \end{equation*}
  is equivalent to $(x_n)_{n=1}^{\infty}$ in $R_{\mathcal{T}_\alpha}^{Y}$, which is in turn equivalent to the Haar system in~$Y$.
  Now it only remains to show that $[\tilde{x}_n]_{n=1}^{\infty}$ is complemented in $R_\omega^{Y}$. To this end, we define the operator $V\colon R_\omega^{Y}\to Y$ by setting, for every $k\in \mathbb{N}_0$ and $z\in R_k^{Y}$,
  \begin{equation*}
    V(J^{\omega}_k z) =
    \begin{cases}
      J^{\alpha}_\beta z, & \text{if } k = k(\beta) \text{ for some } \beta < \alpha, \\
      0, & \text{if } k \notin \{ k(\beta) : \beta < \alpha \}.
    \end{cases}
  \end{equation*}
  Then $V$ is bounded, as it is obtained by projecting $R_\omega^{Y}$ onto a subsequence of its canonical unconditional decomposition and then applying (square function-) distributional isomorphisms with (square function-) independent ranges to the individual components. Moreover, note that $V \tilde{y}_\beta = y_\beta$ for all $\beta < \alpha$ and hence,
  \begin{equation*}
    V \tilde{x}_n = x_n,\qquad n\in \mathbb{N}.
  \end{equation*}
  Finally, let $Q$ be a bounded linear projection from $Y$ onto $R_{\mathcal{T}_\alpha}^{Y}$, and define $\widetilde{P}\colon R_\omega^{Y}\to R_\omega^{Y}$ by
  \begin{equation*}
    \widetilde{P} = UPQV.
  \end{equation*}
  Then $\widetilde{P}(R_\omega^{Y}) \subset U([x_n]_{n=1}^{\infty})\subset [\tilde{x}_n]_{n=1}^{\infty}$, and for every $n\in \mathbb{N}$,
  \begin{equation*}
    \widetilde{P} \tilde{x}_n = UPQx_n = Ux_n = \tilde{x}_n.
  \end{equation*}
  Thus, $\widetilde{P}$ is a projection from $R_\omega^{Y}$ onto $[\tilde{x}_n]_{n=1}^{\infty}$.

  \item[\ref{thm:alternatives:c}$\Longleftrightarrow$\ref{thm:alternatives:d} for $Y = X^0$.]
        In the previous part of the proof, we have already seen that \ref{thm:alternatives:c}$\Longrightarrow$\ref{thm:alternatives:d} if $Y = X^0$.
        Next, suppose that $Y = X^0$ and~\ref{thm:alternatives:d} holds, i.e., there exists an independent sequence $(x_n)_{n=1}^{\infty}$ in $Y$ equivalent to the Haar system whose closed linear span is complemented in $Y$. { Let $J_n\colon Y\to Y$, $n\in \mathbb{N}$, be distributional embeddings with independent ranges. The sequence $(x_n')_{n=1}^{\infty}$ in $(\oplus_{n=1}^{\infty} Y)_{Y,\mathrm{ind}}$, defined by $x_n' = J_n x_n$ for all $n$, is also independent and equivalent to the Haar system, and its closed linear span is complemented in $Y$, since distributional embeddings preserve complementation (see \Cref{lem:distributional-copy-complemented}). Now approximate the functions $x_n'$ by elements of~$J_n(R_{k(n)}^Y)$ for sufficiently large natural numbers $k(1)<k(2)<\cdots$. By permuting the components of $(\oplus_{n=1}^{\infty} Y)_{Y,\mathrm{ind}}$ accordingly, we see that $R_\omega^Y = (\oplus_{k=1}^{\infty} R_k^Y)_{Y,\mathrm{ind}}$
        contains a sequence spanning a complemented copy of $Y$, which, as above, implies~\ref{thm:alternatives:b}.}

  \item[\ref{thm:alternatives:a}$\vee $\ref{thm:alternatives:b}.]
        Finally, assume that~\ref{thm:alternatives:b}, and hence~\ref{thm:alternatives:c}, is false. \Cref{index main theorem}~\ref{index main theorem b} implies that $i_Y[R_\alpha^{Y}] < \omega_1$ for all $\alpha < \omega_1$. We construct $(\alpha_\xi)_{\xi\in \omega_1}$ as follows: Put $\alpha_0 = 0$. Now fix $1 \le \xi < \omega_1$, and assume that $\alpha_\eta$ has already been defined for all $\eta < \xi$. Then $\beta := \sup_{\eta < \xi} i_Y[R_{\alpha_\eta}^{Y}]$ is a countable ordinal, and we put $\alpha_\xi = \beta + 1$. By \Cref{complementex Y index of tree BRS spaces}, we have $i_Y[R_{\beta + 1}^{Y}] \ge \beta + 1$. In particular, for all $\eta < \xi$, we have $i_Y[R_{\alpha_\xi}^{Y}] > i_Y[R_{\alpha_\eta}^{Y}]$, which, by \Cref{index main theorem}~\ref{index main theorem a}, implies that $R_{\alpha_\xi}^{Y}$ and $R_{\alpha_\eta}^{Y}$ are non-isomorphic. Hence,~\ref{thm:alternatives:a} is true.\qedhere
\end{itemize}

The fundamental function of the Orlicz space $L_{\Phi}$ is given by the formula
  \begin{equation*}
    \varphi_{L_{\Phi}}(t) = \frac{1}{\Phi^{-1}(1/t)}, \qquad t\in (0,1].
  \end{equation*}
  Now let $y = \Phi(s)$ for some $s > 0$. Then, as $s \to \infty$, we have $y \sim  s (\log s)^{\alpha}$, and thus,
  \begin{equation}\label{eq:8}
    \log y = \log s + \alpha \log \log s + o(1).
  \end{equation}
  This implies that $\log y \sim \log s$. Plugging $\log s = \log y\, (1 + o(1))$ into the term $\log \log s$ in~\eqref{eq:8} yields
  \begin{equation*}
    \log y = \log s + \alpha \log\log y + o(1).
  \end{equation*}
  Solving for $s$, we obtain
  \begin{equation*}
    \Phi^{-1}(y) = s \sim y (\log y)^{-\alpha}\qquad \text{as }s\to \infty.
  \end{equation*}
  or, equivalently, as $y\to \infty$.
  This implies the first claimed result. The second statement follows from \cite[Chapter~4, Theorem~8.18]{bennett:sharpley:1988}.

  To prove the last statement, we use~(8.37) from the proof of \cite[Chapter~4, Theorem~8.18]{bennett:sharpley:1988}, i.e., $\|T_{[0,t)}\|_{L_{\Phi}\to L_{\Phi}}\le k(2t)$ for $0 < t < 1/2$, where
  \begin{equation*}
    k(t) = \sup \Bigl\{ \frac{\Phi^{-1}(s)}{\Phi^{-1}(s/t)} : 1\le s < \infty \Bigr\},\qquad 0 < t < 1.
  \end{equation*}
  We know that
  \begin{equation*}
    \Phi^{-1}(s)\sim s (\log s)^{-\alpha} \sim s (\log(e + s))^{-\alpha}\qquad \text{as } s\to \infty,
  \end{equation*}
  so
  \begin{equation*}
    s\mapsto \frac{\Phi^{-1}(s)}{s \log(e + s)^{-\alpha}}
  \end{equation*}
  is a continuous function on $[1,\infty)$ that converges to $1$ as $s\to \infty$. Thus, there exist $m,M > 0$ such that
  \begin{equation*}
    m s (\log(e + s))^{-\alpha} \le  \Phi^{-1}(s) \le M s (\log(e + s))^{-\alpha}, \qquad s\in [1,\infty).
  \end{equation*}
  Hence, for every $0 < t < 1$ and $s\in [1,\infty)$,
 \begin{equation*}
    \frac{\Phi^{-1}(s)}{\Phi^{-1}(s/t)} \le \frac{M}{m} t \biggl[ \frac{\log(e+s/t)}{\log(e+s)} \bigg]^{\alpha}
                                       \le \frac{M}{m} t \biggl[ \frac{\log(e+s) + \log(1/t)}{\log(e+s)} \bigg]^{\alpha}
                                       \le \frac{M}{m} t \Bigl[ 1 + \log(1/t) \Bigr]^{\alpha},
 \end{equation*}
 which implies that $k(t) \lesssim t(1 + \log\frac{1}{t})^{\alpha}$. Thus, for $0 < t <1/2$, we obtain $\|T_{[0,t)}\|_{L_{\Phi}\to L_{\Phi}}\le k(2t) \lesssim t (\log\frac{1}{t})^{\alpha}$. The reverse inequality holds because $\|T_{[0,t)}\|_{L_{\Phi}\to L_{\Phi}} \ge  \phi_{L_{\Phi}}(t) \gtrsim t (\log\frac{1}{t})^{\alpha}$.

\label{prop:unboundedness}
  Let $X$ be a Haar system space with $\|\cdot\|_X\not\asymp\|\cdot\|_\infty$ and $Y = X^0$ or $H_X$.
  Let $k\in \mathbb{N}$ and $m = 2^k$, and let $(F_r)_{r=1}^m$ be a $k$-yardstick family. 
  Then the orthogonal projection $P$ from $\langle \{ h_I : I\in \mathcal{D}  \} \rangle$ onto $Y_{F_1} + \dots + Y_{F_m}$ satisfies the following lower bounds: If $Y = H_X$, then
  \begin{equation}\label{eq:4}
    \min\{ \|P\|_{Y\to Y}, \|P\|_{Y\to X^0} \}
     \gtrsim \frac{m^{-m}}{\varphi_X(m^{-m})} \sqrt{m}.
  \end{equation}
  If $Y = X^0$ and $(r_n)_{n=0}^{\infty}$ in $X$ is equivalent to the unit vector basis of $\ell_2$, then
  \begin{equation}\label{eq:7}
    \|P\|_{Y\to Y} \gtrsim \frac{m^{-m}}{\|T_{[0, m^{-m})}\|_{Y\to Y}} \sqrt{m}.
  \end{equation}
  The implied constants in~\eqref{eq:4} and~\eqref{eq:7} depend only on the underlying space.

For $r = 1,\dots,m$, let $|F_r| = k_r + 1$, and let $\max F_r$ denote the largest and $s_r$ the second-largest element of $F_r$.
  Let $n\in \mathbb{N}$ be as in \Cref{dfn:yardstick-family} and note that $s_r \le n - 1$.
  Choose a collection $\mathcal{B}_r\subset \mathcal{D}_{k_r}$ such that the function
  \begin{equation*}
    f_r = \sum_{I\in \mathcal{B}_r} b_I^{F_r},
  \end{equation*}
  satisfies $|\operatorname{supp} f_r| = 2^{-k} =: \rho$. Define
  \begin{equation*}
    A = \bigcap_{r=1}^m \operatorname{supp} f_r.
  \end{equation*}
  Note that for every $I\in \mathcal{D}_{k_r}$, the set $\operatorname{supp} b_I^{F_r} = [b_{\pi(I)}^{F_r} = \varepsilon(I)]$ is $\sigma(\mathcal{D}^{s_r + 1})\subset \sigma(\mathcal{D}^{n})$-measurable, so $\operatorname{supp} f_r$ is $\sigma(\mathcal{D}^n)$-measurable as well for every $r$. Hence, $A$ is $\sigma(\mathcal{D}^n)$-measurable and, by independence, $|A| = \rho^m$. Now define
  \begin{equation*}
    f = \sum_{r=1}^m f_r \chi_A.
  \end{equation*}
  Since $\max F_r \ge n$ for all $r$, we see that every $K$ in the Haar support of $f_r$ is either a subset of $A$ or disjoint from $A$. Thus,
  \begin{equation*}
    f = \sum_{r=1}^m \sum_{\substack{K\in \mathcal{D}^{\max F_r}\\ K\subset A}} h_K = \chi_A\sum_{r=1}^m r_{\max F_r}\qquad \text{and} \qquad S(f) =  \sqrt{m}\, \chi_A.
  \end{equation*}
  This implies that $\|f\|_Y = \sqrt{m}\, \|\chi_A\|_X$ if $Y = H_X$, and $\|f\|_Y \lesssim  \sqrt{m}\, \|T_{[0,|A|)}\|_{Y\to Y}$ if $Y = X^0$, assuming that $(r_n)_{n=1}^{\infty}$ in $X$ is equivalent to the unit vector basis of $\ell_2$.

  The orthogonal projection onto $Y_{F_1} + \dots + Y_{F_m}$ is given by
  \begin{equation}\label{eq:20}
    Px = \sum_{r=1}^m \mathbb{E}_{F_r}x = \sum_{r=1}^m \sum_{I\in \mathcal{D}_{k_r}} |I|^{-1} \langle b_I^{F_r}, x \rangle b_I^{F_r},\qquad  x\in \langle \{ h_I : I\in \mathcal{D} \} \rangle.
  \end{equation}
  Observe that
  \begin{equation*}
    \langle b_I^{F_r}, b_J^{F_s} \chi_A \rangle = 0
  \end{equation*}
  for $r,s\in \{ 1,\dots,m \}$ and $I\in \mathcal{D}_{k_r}$, $J\in \mathcal{D}_{k_s}$, unless $r = s$ and $I = J$. Thus, for the function~$f$ defined above, we obtain
  \begin{equation*}
    Pf = \sum_{r=1}^m \sum_{I\in \mathcal{B}_r} |I|^{-1} \langle b_I^{F_r}, b_I^{F_r} \chi_A \rangle b_I^{F_r}.
  \end{equation*}
  By independence, we have
  \begin{equation*}
    \langle b_I^{F_r}, b_I^{F_r} \chi_A \rangle = |\operatorname{supp}(b_I^{F_r})\cap A| = |I|\cdot \frac{|A|}{|\operatorname{supp} f_r|} = \rho^{-1}|I| |A|,
  \end{equation*}
  which implies that
  \begin{equation*}
    Pf = \rho^{-1}|A| \sum_{r=1}^m \sum_{I\in \mathcal{B}_r} b_I^{F_r} = \rho^{-1}|A|\sum_{r=1}^m f_r
  \end{equation*}
  and
  \begin{equation*}
    S(Pf) = \rho^{-1}|A| \Bigl( \sum_{r=1}^m |f_r| \Bigr)^{1/2}.
  \end{equation*}
  The functions $|f_r|$ are $\{ 0,1 \}$-valued, independent, and ``almost'' disjointly supported in the following sense: We have $|\operatorname{supp} f_r| = \rho =  \frac{1}{m}$ for all $r=1,\dots,m$, which implies that
  \begin{equation*}
    \bigl|\bigl[|f_r| = 1 \wedge |f_s| = 0\ \forall s\ne r\bigr]\bigr| \ge  \rho \Bigl( 1 - \frac{1}{m}\Bigr)^m \ge \frac{\rho}{4}
  \end{equation*}
  for all $r$. Hence, there exist $m$ pairwise disjoint sets, each of measure at least $\rho/4$, on which
  \begin{equation*}
    |Pf| = S(Pf) = \rho^{-1}|A|.
  \end{equation*}
  Thus, for any Haar system space $X$ and $Y = X^0$ or $H_X$, we have
  \begin{equation*}
    \|Pf\|_Y \ge \rho^{-1}|A|\cdot  \|\chi_{[0,\, m \rho/4 )}\|_X.
  \end{equation*}
  Altogether, if $Y = H_X$, we obtain
  \begin{equation}\label{eq:18}
    \frac{\|Pf\|_Y}{\|f\|_Y} \gtrsim \frac{\rho^{-1}|A|\cdot \|\chi_{[0,m\rho/4)}\|_X}{\sqrt{m}\|\chi_A\|_X} \gtrsim  \frac{\varphi_X(m\rho)/(m\rho)}{\varphi_X(\rho^m)/\rho^m} \sqrt{m}.
  \end{equation}
  Since $m\rho = 1$, the last inequality simplifies to~\eqref{eq:4}.
  In passing, we note that $\varphi_X(t)/t = \varphi_{X'}(t)$ for $t\in (0,1]$, where $X'$ is the associate space of $X$.
  If $Y = X^0$, we need to replace $\|\chi_A\|_X$ with $\|T_{[0,|A|)}\|_{Y\to Y}$ in~\eqref{eq:18}, which yields~\eqref{eq:7}.

We prove the claimed result in several steps.
\setcounter{clm}{0}
\begin{clm}
\label{computing by pruning}
For every $F\in\mathcal{T}$,
\[o[\mathcal{T}_F] = \max\{\alpha:F\in\mathcal{T}^{(\alpha)}\}.\]
In particular, $o[\mathcal{T}]\geq \#F+o[\mathcal{T}_F]$.
\end{clm}
\noindent \emph{Proof.} This is proved with an induction on $\mathcal{T}$ starting at the leaves. The second part is then obvious.\hfill$\scriptstyle\square$


\begin{clm}
For every $\alpha\leq o[\mathcal{T}]$ there exists $F\in\mathcal{T}$ such that $o[\mathcal{T}_F] = \alpha$.
\end{clm}

\noindent \emph{Proof.} One just picks a maximal $F\in\mathcal{T}^{(\alpha)}$.\hfill$\scriptstyle\square$


\begin{clm}
\label{infinitely many successors}
If $n\in\mathbb{N}_0$ and $o[\mathcal{T}] = \omega+n$ then there exists $F\in\mathcal{T}$ such that $\#F = n$ and the set $S_F = \{k>\max(F):F\cup\{k\}\in \mathcal{T}\}$ is infinite.
\end{clm}

\noindent \emph{Proof.} If $n = 0$, this means that there are infinitely many singletons in $\mathcal{T}$. If $\mathcal{T}$ contained only finitely many singletons, say defined by  $k_1,\ldots,k_n$, then, letting $\mathcal{T}_i = \{F\in\mathcal{T}:\min(F) = k_i\}$, we would have
\[o[\mathcal{T}] = \max_{1\leq i\leq n} o[\mathcal{T}_i] \geq \max_{1\leq i\leq n}o[\mathcal{T}_{\{k_i\}}]+1,\]
which is an infinite successor ordinal.

If $o[\mathcal{T}] = \omega+n$, then $o[\mathcal{T}^{(\omega)}] = n$, which yields a maximal element $F\in\mathcal{T}^{(\omega)}$ with $\#F = n$. In particular, by \Cref{computing by pruning}, $o[\mathcal{T}_F] =\omega$, which by the case $n=0$ yields that $S_F$ is infinite.\hfill$\scriptstyle\square$\medskip

Now, for every $n\in\mathbb{N}$ let  $G_n\in\mathcal{T}$ such that  $o[\mathcal{T}_{G_n}] = \omega+k_n$, with $k\leq k_1<k_2<\cdots$. We note that, in particular, $G_n\neq G_m$, for $n\neq m$. By the compactness of $[\mathbb{N}_0]$ (identified, as usual, with $\{0,1\}^{\mathbb{N}_0}$, via $A\mapsto\chi_A$), and by passing to a subsequence, there exists $F\in[\mathbb{N}_0]$ such that
\begin{equation}\label{eq:19}
  G_n\cap\{0,\ldots,n\} = F\cap\{0,1\ldots,n\} \qquad \text{for all } n\in \mathbb{N}.
\end{equation}
We deduce $F\cap\{0,1\ldots,n\}\in\mathcal{T}$, and because $\mathcal{T}$ is well-founded, $F$ must be finite. By passing to a further subsequence, we may now assume that $G_n\cap G_m = F$, for all $n\neq m$. For all $n=1,\ldots,m$ pick $H_n\in\mathcal{T}_{G_n}$ such that $\#H_n = k_n\geq k$ and $S_{H_n}$ is infinite. Let $N = \max\{H_1\cup\cdots\cup H_m\}$ and, for $1\leq n\leq m$, choose $\ell_n\in S_{H_n}\cap\{N+1,\ldots\}$. Define $F_n = (G_n\setminus F)\cup H_n\cup\{\ell_n\}\in\mathcal{T}_F$, and note that the sets $F_1,\dots,F_m$ are pairwise disjoint.

\phantom{}
  \begin{enumerate}[label=(\alph*)]
  \item[\ref{thm:tree-spaces-uncomplemented:a}]
  Let $Y$ be one of the spaces listed in the theorem, and let $\mathcal{T}$ be a well-founded disjointly branching tree with $o[\mathcal{T}] \ge \omega\cdot 2$. By \Cref{prop:existence-of-yardstick-families-in-trees}, for every $k\in \mathbb{N}$ and $m = 2^k$, we can find $F\in\mathcal{T}$ and a $k$-yardstick family $F_1,\ldots,F_m$ in $\mathcal{T}_F$. Now let $P_{\mathcal{T}}$ denote the orthogonal projection from $\langle\{  h_I : I\in \mathcal{D}  \}\rangle$ onto $\langle Y_G : G\in \mathcal{T} \rangle$. We claim that
  \begin{equation}\label{eq:21}
    \|P_\mathcal{T}\| \geq \Big\|\mathbb{E}_{\cup_{n=1}^m F_n}P_\mathcal{T}\Big\| = \Big\|\sum_{n=1}^m \mathbb{E}_{F_n}\Big\|.
  \end{equation}
  Indeed, the last equality follows from \Cref{expectations on subsets are a monoid}: Let $H = \cup _{n=1}^m F_n$, then for $g\in \langle \{ h_I : I\in \mathcal{D} \} \rangle$, we have
  \begin{equation*}
    \mathbb{E}_H P_\mathcal{T}g = \sum_{G\in \mathcal{T}\setminus \{ \emptyset \}} \mathbb{E}_H (\mathbb{E}_G - \mathbb{E}_{G'})(g) = \sum_{G\in \mathcal{T}\setminus \{ \emptyset \}} (\mathbb{E}_{H\cap G} - \mathbb{E}_{H\cap G'})(g).
  \end{equation*}
  Note that $H\cap G = H\cap G'$ unless $\max G \in H$, i.e., $\max G \in F_n$ for some $n\in \{ 1,\dots,m \}$. Thus, we obtain
  \begin{equation*}
    \mathbb{E}_H P_{\mathcal{T}}g = \sum_{n=1}^m \sum_{\substack{K\in \mathcal{T}_F\\ K\sqsubseteq F_n}} (\mathbb{E}_K - \mathbb{E}_{K'})(g) = \sum_{n=1}^m \mathbb{E}_{F_n}g,
  \end{equation*}
  which proves~\eqref{eq:21}.

  Next, observe that the right-hand side of~\eqref{eq:21} is the norm of the orthogonal projection from $\langle \{ h_I : I\in \mathcal{D} \} \rangle$ onto $Y_{F_1} + \dots + Y_{F_m}$, see~\eqref{eq:20}. By \Cref{cor:norm-P-tends-to-infty}, this norm tends to infinity as $k\to \infty$. Thus, $P_{\mathcal{T}}$ is unbounded and therefore does not extend to a bounded linear operator on $Y$. By \Cref{BRS orthocomplemented or not at all}, this implies that $R_{\mathcal{T}}^{Y}$ is uncomplemented in~$Y$. In particular, the conclusion holds for $\mathcal{T} = \mathcal{T}_\alpha$ if $\omega \cdot 2 \le \alpha < \omega_1$, since $o[\mathcal{T}_\alpha] = \alpha$ (see \Cref{rem:order-of-ordinal-trees}).

  \item[\ref{thm:tree-spaces-uncomplemented:b}]
  It is clear that the tree $\mathcal{T}_{\omega}$ can be constructed in such a way that for every $k,m \in \mathbb{N}$, there exists a $k$-yardstick family $F_1,\dots,F_m$ in $\mathcal{T}_\omega$ (this is evident from the structure of the tree and a suitable labeling to its nodes).
  Analogously, every tree $\mathcal{T}_{\omega + n}$, $n\in \mathbb{N}_0$, can be constructed so that for every $k,m \in \mathbb{N}$, there exist $F\in \mathcal{T}_{\omega + n}$ and a $k$-yardstick family $F_1,\dots,F_m$ in $(\mathcal{T}_\omega)_F$.
Hence, as above, $R_{\omega + n}^Y$ is uncomplemented in $Y$.

\item[\ref{thm:tree-spaces-uncomplemented:c}]
          For $n = 0$, let $\mathcal{T}_\omega$ be constructed as in \Cref{exa:ordinal-trees}. Then, by a result of M\"uller and Schechtman~\cite{mueller:schechtman:1989}, $R_\omega^{H^1}$ is complemented in $H^1$ by a bounded linear projection~$P$. For $n = 1,2,\dots$, note that by iterating~\eqref{showing these are really BRS spaces eq1} in \Cref{showing these are really BRS spaces},
          \begin{equation*}
            R_{\mathcal{T}_{\omega + n}}^{H^1} = \langle \{ h_I : I\in \mathcal{D}_{n-1} \} \rangle + \sum_{I\in \mathcal{D}^n} T_I(R_{\mathcal{T}_\omega}^{H^1}).
          \end{equation*}
          For $y\in \langle \{ h_I : I\in \mathcal{D}_{n-1} \} \rangle$ and $x_I \in H^1$, $I\in \mathcal{D}^n$, put
          \begin{equation*}
            \widetilde{P}\Bigl( y + \sum_{I\in \mathcal{D}^n} T_I x_I \Bigr) = y + \sum_{I\in \mathcal{D}^n} T_I Px_I.
          \end{equation*}
          Then $\widetilde{P}$ is a bounded linear projection from~$H^1$ onto $R_{\mathcal{T}_{\omega + n}}^{H^1}$ with $\|\widetilde{P}\|\le 1 + 2\|P\|$.
